programs.sol:
"""A lexical detector for general-reference knowledge and online resources.

Encyclopedias and wiki URLs receive the largest values. Dictionaries,
information/knowledge words, search, and web resources receive smaller ones.
A short text tail distinguishes reference URLs from email/code addresses and
recognizes reference phrases such as 'search results' and 'Wikipedia articles'.
The wiki label and Chinese encyclopedia label get extra weight at document
starts. Other tokens receive zero, except for a small negative value on the
HTTP/HTTPS protocol names. This is a coarse approximation; weaker signed and
context-specific responses remain.
"""

READS = ()

# Approximate strengths of familiar reference and online-resource vocabulary.
# Multilingual terms include encyclopedia, knowledge, information, and websites.
WORD_GROUPS = (
    (3.6, 'wikipedia encyclopedia encyclopaedia encyclopedias'),
    (4.5, '百科'),
    (1.3, 'dictionary dictionaries wiki webster 大全 百度 网友 yahoo ebay'),
    (1.1, 'faq faqs 知识 知識 资料 資料 问答 答疑 搜索引擎'),
    (0.85, 'definitions 解答 搜索 ホームページ'),
    (0.8, 'knowledge knowledgeable factual handbook 懂 的回答'),
    (0.7, 'information online 网 網 网页 インターネット 教程 онлайн'),
    (0.55, 'definition informative terminology calculator guide internet '
           'интернет информацию информация портал'),
    (0.4, 'documentation manual search searching google amazon youtube pubmed '
          'forum forums lookup 信息 情報 解释 小编 本站 本网 ページ'),
    (0.3, 'reference resource resources literature textbook textbooks '
          'website websites browse web page links info 网上 互联网 '
          'информации información informationen'),
    (0.4, 'page articles'),
    (0.25, 'list table article facebook サイト 网站 網站 查询'),
    (0.15, 'doc library'),
    (0.1, 'references tutorials index'),
)
WORDS = {word: value for value, words in WORD_GROUPS for word in words.split()}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        tail = ''
    else:
        tail = carry[1]
    raw = prefix.token_strings[-1]
    token = raw.strip().lower()
    word = token.lstrip('/._-')
    value = WORDS.get(word, 0.0)

    # Wiki names may be split within a word or fused to a URL separator.
    if token == 'ikipedia':
        value = 4.2
    elif token == '.wikipedia':
        value = 2.7
    elif token == '/wiki':
        value = 5.0
    elif token == 'wiki' and not raw.startswith(' '):
        value = 2.1
    elif word == 'docs':
        value = 0.2 if raw.startswith((' ', '_')) else 0.7
    elif token == '_dictionary':
        value = 0.4
    elif word == 'definitions' and not raw.startswith(' '):
        value = 0.4
    elif token == '-doc':
        value = 0.7
    elif token in {'/doc', '/reference', '/forum', '/questions'}:
        value = {'/doc': 0.5, '/reference': 1.0, '/forum': 0.8,
                 '/questions': 1.8}[token]
    elif token in {'.md', '.html', '.htm', '.php'}:
        value = 0.15

    # URL suffixes depend on the kind of address they finish.
    if token in {'.com', '.org', '.net', '.gov', '.uk'}:
        value = 0.55
        if token == '.org' and 'wiki' in tail[-50:]:
            value = 3.8
        elif token == '.com' and ('github' in tail[-20:] or '@' in tail[-45:]):
            value = 0.25
        elif '://' in tail[-100:]:
            value = 0.9
        elif token == '.com':
            value = 0.6
        if raw == '.NET':
            value = 0.2
    elif word == 'www':
        value = 0.75 if tail.endswith('//') else 0.23
    elif word == 'links':
        value = 0.85 if tail.rstrip().endswith('external') else 0.25
    elif word in {'engine', 'engines'} and tail.rstrip().endswith('search'):
        value = 1.4
    elif word == 'article' and 'wiki' in tail[-20:]:
        value = 2.5
    elif token in {'http', 'https'}:
        value = -0.14

    # Complete familiar reference phrases rather than boosting all later tokens.
    previous = tail.rstrip().rsplit(None, 1)[-1] if tail.strip() else ''
    if previous in {'wiki', 'wikipedia'}:
        if word in {'article', 'articles', 'page', 'pages'}:
            value = 4.5 if previous == 'wikipedia' else 2.5
        elif word == 'user':
            value = 2.6
    elif previous in {'search', 'searching'}:
        if word == 'results':
            value = 1.6
        elif word == 'for':
            value = 0.45
        elif word == 'on':
            value = 0.85
    elif previous in {'guide', 'handbook'} and word in {'to', 'on', 'for'}:
        value = 0.55
    elif word == 'of':
        if previous in {'encyclopedia', 'encyclopaedia', 'dictionary'}:
            value = 1.0
        elif previous in {'list', 'table', 'definition', 'definitions'}:
            value = 0.2
    if token == '典' and tail.endswith('辞'):
        value = 4.2  # Japanese 辞典, a dictionary.
    elif token == '典' and tail.endswith('字'):
        value = 1.0  # Chinese 字典, a dictionary.
    elif token == '名片' and tail.endswith('百科'):
        value = 2.7  # Baidu-style encyclopedia profile heading.
    elif token == 'lopedia' and (tail + token).endswith('enciclopedia'):
        value = 3.5
    if first and word == '百科':
        value = 10.9
    elif first and word == 'wiki':
        value = 6.0

    return (doc, (tail + raw.lower())[-120:]), float(value)

programs.haiku:
READS = ()
"""Web and reference vocabulary detector (layer-0 MLP, component 64).

The component writes into the residual stream when the current token names an online
source or a reference work: web addresses (.com, .org, www, wiki), encyclopedias and
dictionaries, and words about information, knowledge, the internet and search.
It is roughly 0 on ordinary words and punctuation.
"""
TOP = {".com", ".org", ".net", "www", "/wiki", "wiki", ".wikipedia", " Encyclopedia",
       " Dictionary", " encyclopedia", " dictionary"}
MID = {" information", " knowledge", " online", " Online", " internet", " Internet", " web",
       " Web", " search", " links", " guide", " Google", " engines", " website", " reference",
       "网", "网友", "百度", "知识", "资料", " definitions", " definition", " FAQ"}
LOW = {" page", " table", " Table", " list", " resources", "/resources", " Library", " article",
       " terms", " questions", " calculator", "http", "://", " Guide", " reference"}

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if s in TOP:
        return None, 1.0
    if s in MID:
        return None, 0.5
    if s in LOW:
        return None, 0.2
    return None, 0.0

"""Riding-and-boarding detector (negative).

Layer-0 MLP output feature (component 65 of layer 0's down_proj). It acts on the word
itself: it goes negative on words for riding or boarding a vehicle or animal, and for
their Chinese and Japanese characters (乘, 骑, 搭, 登, 驾, 坐 ...). It is weaker for
passengers, boarding, and for people and actions of operating a vehicle (pilot, crew,
driver, driving, fly, climb). The character 乘 also means "multiply", so the English
"multiply" words get a weak negative value too. Everything else is 0. The values are
per-class means measured on training text; the program keeps no context.
"""
from collections.abc import Mapping

READS = ()

# Riding and mounting characters, strongest first (mean activation about -2.5 to -5).
RIDE_CJK_STRONG = {"乘", "乗", "乘客", "乗り", "に乗", "骑", "騎", "驾", "驾驶", "驶", "踩", "踏", "搭"}
# Milder riding and sitting characters (about -1).
RIDE_CJK_MILD = {"登", "坐", "坐在", "行驶", "穿", "载", "凌", "趁", "承"}
# English words for riding.
RIDE_EN = {"ride", "rides", "riding", "rode", "ridden", "rider", "riders"}
# Passengers and boarding.
BOARD_EN = {"passenger", "passengers", "boarding", "aboard", "embark", "board", "boards", "onboard"}
# Vehicle operators and motion.
OPERATE_EN = {"pilot", "crew", "driver", "drivers", "driving", "drive", "captain", "navigator",
              "fly", "flying", "cruise", "sailing", "sail", "climb", "climbing", "climbed",
              "climbs", "cavalry", "bike", "bikes", "cabin"}
# Multiplication words (乘 means multiply in Chinese).
MULTIPLY_EN = {"multiply", "multiplied", "multiplying", "multiplication", "multiplier"}


def step(carry, prefix, upstream: Mapping):
    raw = prefix.token_strings[-1].strip()
    word = raw.lower()
    if raw in RIDE_CJK_STRONG:
        value = -3.0
    elif raw in RIDE_CJK_MILD:
        value = -1.0
    elif word in RIDE_EN:
        value = -1.5
    elif word in BOARD_EN:
        value = -0.8
    elif word in OPERATE_EN:
        value = -0.5
    elif word in MULTIPLY_EN:
        value = -0.4
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Recognize word forms for knowing, knowledge, and being known.

The main signal is negative on 'know' and its inflections, and stronger on
知, the Chinese/Japanese character for knowing. Longer knowledge words and
translations have weaker responses. Several short phrases and split-word
endings prolong this lexical signal. Everything else is predicted as zero;
this does not attempt to decide whether a statement is actually true.
"""

READS = ()

# Fragments of Spanish, French, Italian, Portuguese and German 'know/known'.
KNOW_ROOTS = ('conoc', 'conna', 'conosc', 'conhec', 'bekan')
KNOW_TRANSLATIONS = {'wissen', 'kennen', 'bekannt', 'извест', 'зна',
                     'знаю', 'знать', 'знает', 'biết'}
AWARENESS = {'aware', 'unaware', 'ignorant', 'knowledgeable'}
FAMILIARITY = {'awareness', 'acquaintance', 'savvy', 'famous', 'renowned',
               'renown', 'notorious', 'weiß', 'sabe', '智慧', '著名', '闻名'}


def lexical(token):
    word = token.strip().lower()
    bare = word.lstrip('._(-')
    if bare in {'know', 'known'}:
        if bare == 'known' and word.startswith('-'):
            return -1.65
        if bare == 'known' and not token.startswith(' '):
            return -1.90
        return -2.28
    if bare in {'knows', 'knew'}:
        return -2.08
    if bare == 'knowing':
        return -2.53
    if bare in {'unknown', 'unknow', 'knowingly'}:
        return -1.60
    if bare == 'knowledge':
        return -1.48 if token.startswith(' ') else -1.20
    if bare in AWARENESS:
        return -0.65
    if bare in FAMILIARITY:
        return -0.40
    if word == '知':
        return -5.20
    if word in {'知道', '不知', '可知', '明知'}:
        return -3.05
    if '不知道' in word or word == '未知':
        return -1.95
    if word in {'想知道', '谁知道'}:
        return -1.15
    if '知道' in word or word in {'得知', '知情', '知晓'}:
        return -2.30
    if word.endswith(('知识', '知識')) or word in {
            '知名', '知己', '告知', '熟知', '深知', '可想而知', '知って'}:
        return -1.40
    if word in {'智', '通知', '认知', '知らない', '感知', '了解到', '获悉', '지'}:
        return -0.90
    if word in {'了解', '懂', '懂得', '不懂', '알', '알고', '알려', 'notified'}:
        return -0.55
    if word.startswith(KNOW_ROOTS) or word in KNOW_TRANSLATIONS:
        return -1.10
    if word in {'зн', 'узнать', 'عرف', 'يعرف'}:
        return -0.80
    if word in {'info', '_info', '-info', 'informed', 'cognitive'}:
        return -0.25
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = '' if carry is None or carry[0] != doc else carry[1]
    value = lexical(token)
    # Decode the prefix only for incomplete Unicode tokens that may finish 知.
    if '�' in token and prefix.text_prefixes[-1].endswith('知'):
        value = -5.60
    if word == 'know' and previous in {'me', 'us', 'them'}:
        value = -1.85
    elif word == 'know' and previous == 'to':
        value = -2.42
    elif word == 'known' and previous == 'is':
        value = -2.49
    if previous == 'knowledge' and word == 'of':
        value = -0.75
    elif previous == 'known' and word in {'to', 'for'}:
        value = -0.52 if word == 'to' else -0.35
    elif previous in {'know', 'knows', 'knew', 'known', 'knowing'}:
        if word in {'the', 'that'}:
            value = -0.29 if word == 'the' else -0.13
    elif previous == 'извест' and word in {'но', 'ной', 'ный', 'ны'}:
        value = -0.70
    elif previous.startswith('conoc') and word in {'ido', 'ida', 'idos', 'idas'}:
        value = -0.77
    return (doc, word), float(value)

programs.haiku:
"""Knowing-words detector.

The component is a negative "knowing" feature. It goes strongly negative on the
word for knowing itself ("know", "known", "knew", "knowing", "knowledge", "unknown",
and the Chinese 知 / 知道 / 不知), and more weakly negative on words for being
informed or aware ("aware", "informed", "ignorant", "famous", "renowned",
"了解", "懂") and on a preposition right after a know-word ("known to", "knowledge of").
Everywhere else it predicts 0.
"""
READS = ()

# Forms of "to know": strongest.
KNOW_VERBS = {"know", "known", "knew", "knows", "knowing"}
# Nouns and adjectives built on "know".
KNOW_NOUNS = {"knowledge", "knowledgeable", "unknown"}
# Chinese for "know" and compounds.
ZH_KNOW = {"知": -4.8, "知道": -3.0, "不知": -3.0, "不知道": -1.9, "知识": -1.5}
# Words about being informed or aware: weaker.
AWARE = {"aware", "awareness", "informed", "ignorant", "ignorance", "famous",
         "renowned", "notorious", "了解", "懂", "获悉"}
# Prepositions that pick up part of the signal right after a know-word.
FOLLOW = {"of", "to", "for", "about", "the"}
KNOW_ALL = KNOW_VERBS | KNOW_NOUNS


def step(carry, prefix, upstream):
    i = prefix.position
    tok = prefix.token_strings[i].strip().lower()
    if tok in ZH_KNOW:
        return None, ZH_KNOW[tok]
    if tok in KNOW_VERBS:
        return None, -2.3
    if tok in KNOW_NOUNS:
        return None, -1.6
    if tok in AWARE:
        return None, -0.5
    if i > 0 and tok in FOLLOW and prefix.token_strings[i - 1].strip().lower() in KNOW_ALL:
        return None, -0.5
    return None, 0.0

programs.luna:
"""Give a negative pulse to tokens in a small knowing-and-knowledge vocabulary."""
READS = ()

KNOWING_WORDS = {
    "know", "knows", "known", "knew", "knowing", "knowledge", "unknown",
    "知", "智", "知识", "了解", "知道", "不知道", "通知", "知識",
    "biết", "conocer", "извест",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().casefold()
    return None, -2.0 if token in KNOWING_WORDS else 0.0

programs.sol:
"""A partial recognizer of stock code, document markup, and license wording.

Predict negative pulses for selected library-qualified names, generated GUI
layout calls, and software-license clauses; positive pulses for selected
reference/link labels. Chat delimiters have smaller signed responses.
These fixed pattern means leave most ordinary text at zero and do not explain
all of the component's word-specific or context-dependent variation.
"""
import re

READS = ()
PROTOCOL = {
    '<tool_call>': -0.30, '</tool_call>': -0.22,
    '<tool_response>': 0.20, '</tool_response>': 0.28,
    '<think>': -0.34, '</think>': 0.15,
}
SPRING_MODULES = {'web', 'data', 'beans', 'context', 'boot', 'stereotype'}
SPRING_SUBMODULES = {'domain', 'repository', 'bind', 'annotation'}
DOTNET_NAMESPACES = {'Collections', 'Generic', 'Linq', 'ComponentModel'}
ANDROID_MODULES = {'view', 'content', 'support', 'permission'}
DOM_CONSTRUCTION = {'createElement', 'createTextNode', 'setAttribute'}
DOM_LOOKUP = {'getElementById', 'getElementsByTagName',
              'querySelector', 'querySelectorAll'}
COLLECTION_IMPLEMENTATIONS = {'ArrayList', 'HashMap', 'Collections'}
LEGAL_TERMS = {'ANY', 'KIND', 'WARRANTY', 'WARRANTIES', 'PARTICULAR',
               'OTHERWISE', 'ACTION', 'CONTRACT', 'OR', 'LIABILITY'}


def license_word(word, history):
    if not re.search(r'License|Licensed|SOFTWARE|COPYRIGHT|WARRANT', history):
        return None
    if word == 'License' and re.search(r'the [\\]*"$', history):
        return -6.0
    if word == 'License' and history.endswith('Apache'):
        return -3.2
    if word == 'under' and history.endswith('Licensed'):
        return -3.0
    if word == 'sublicense':
        return -3.5
    if word == 'PROVIDED' and history.endswith('SOFTWARE IS'):
        return -4.7
    if word == 'AUTHORS':
        return -3.4
    if word == 'CLAIM':
        return -3.8
    if word in {'MERCHANTABILITY', 'NONINFRINGEMENT'}:
        return -2.0
    if word == 'BASIS' and 'AS IS' in history[-40:]:
        return -3.5
    if word == 'required' and history.rstrip().endswith('Unless'):
        return -2.5
    if word in LEGAL_TERMS or word == 'GNU':
        return -0.9
    if word == 'hope' and history.endswith('in the'):
        return -1.8
    if word == 'should' and history.endswith('You'):
        return -1.0
    if word == 'or' and history.endswith('MERCHANTABILITY'):
        return -1.0
    return None


def qualified_name(name, line, history):
    value = -0.05 if name[0].isupper() or name.islower() else -0.14
    if re.search(r'\b(import|using|package)\b', line):
        if 'org.springframework' in line:
            if name in SPRING_MODULES:
                value = -3.1
            elif name == 'factory' and line.endswith('.beans'):
                value = -5.5
            elif name in SPRING_SUBMODULES:
                value = -2.0
        elif 'android' in line:
            if name in ANDROID_MODULES:
                value = -2.2
            elif name in {'widget', 'os'}:
                value = -0.9
        elif 'System' in line and name in DOTNET_NAMESPACES:
            value = -1.7
    if name in DOM_CONSTRUCTION:
        value = -1.1
    elif name in DOM_LOOKUP:
        value = -0.4
    elif name in COLLECTION_IMPLEMENTATIONS:
        value = -1.0
    elif name == 'IOException' and line.endswith('java.io'):
        if 'BufferedReader' in history:
            value = -4.3
    elif name == 'client' and line.endswith('boto3'):
        value = 2.6
    elif name == 'defineProperty' and line.endswith('Object'):
        value = -1.5
    elif name in {'getItem', 'setItem'}:
        if line.endswith(('localStorage', 'sessionStorage')):
            value = -1.2
    elif name == 'ArgumentParser' and line.endswith('argparse'):
        value = -1.4
    elif name in {'title', 'xlabel', 'ylabel', 'figure'} and line.endswith('plt'):
        value = -1.5
    elif name == 'onCreate' and line.endswith('super'):
        value = -6.0
    elif name == 'from' and line.endswith('LayoutInflater'):
        value = -2.6
    elif name == 'springframework' and line.endswith('org'):
        value = -0.6
    elif name == 'apache' and line.endswith('org'):
        value = -0.5
    elif name == 'unsplash' and line.endswith('images'):
        value = -0.93
    elif name == 'com' and line.endswith('.unsplash'):
        value = -1.25
    elif name == 'org' and line.endswith('.gnu'):
        value = -2.9
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, line = '', ''
    else:
        _, history, line = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0
    if token.startswith('.') and len(token) > 1 and token[1].isalpha():
        value = qualified_name(token[1:], line, history)

    # Generated Swing layout syntax: groups, alignment, and component sizes.
    if 'Layout' in history or 'swing' in history:
        if word.lstrip('.') in {'createParallelGroup', 'addGap'}:
            value = -4.4
        elif word in {'.GroupLayout', '.setHorizontalGroup', '.setVerticalGroup',
                      '.LEADING', '.TRAILING'}:
            value = -3.0
        elif word.lstrip('.') in {'createSequentialGroup', 'addComponent',
                                  'addPreferredGap', 'Alignment'}:
            value = -2.2
        elif word == '_SIZE':
            value = -1.5

    # Documentation attributes, reference labels, and familiar URL fields.
    if word == '-type' and history.endswith('ref'):
        value = 0.90
    elif word in {'-Type', '-Version'} and line.endswith(('Content', 'MIME')):
        value = -0.75
    elif word == 'param' and line.rstrip().endswith(('<', '</')):
        value = -0.85
    elif word == 'reports' and line.endswith('/scientific') and 'nature.com' in line:
        value = 0.65
    elif word == '/rules' and 'eslint.vuejs.org' in history:
        value = 0.9
    elif word == '/repos' and 'github.com' in history:
        value = 0.8
    elif word == 'permalink':
        value = 0.8
    elif word == 'Measurements' and history.rstrip().endswith('Weights and'):
        value = 0.65
    elif word == '/licenses':
        value = -1.5
    elif word == '/questions' and 'stackoverflow' in history:
        value = -2.0
    elif word in {'=format', '&w'} and 'auto=format' in history + token:
        value = -0.5
        if 'images.unsplash.com' in history:
            value = -3.0 if word == '=format' else -2.7
    elif word == 'line' and ('Traceback' in history or 'File "' in history):
        value = -0.45
    elif word == '_argument' and line.endswith('.add') and 'parser' in history:
        value = -1.7

    legal = license_word(word, history)
    if legal is not None:
        value = legal
    value = PROTOCOL.get(word, value)
    history = (history + token)[-400:]
    line = (line + token).split('\n')[-1][-400:]
    return (doc, history, line), float(value)

programs.haiku:
"""Layer-0 MLP output feature, component 67 of layers.0.mlp.down_proj.

In plain terms: a sparse feature that is pushed negative by the vocabulary of Java/Swing
GUI layout code, Android and Spring framework names, and software-license boilerplate,
and pushed mildly positive by a few exception and service-API names and by the closing
tag of a tool response. Most tokens are near zero.

The program is a readable word list. Each group gets a fixed weight close to half the
average activation measured on training text, because the full-size averages over-shoot
on the many tokens that merely look like these words.

  SWING_LAYOUT   (-1.5): NetBeans/Swing GroupLayout builder calls and alignment constants
  FRAMEWORK      (-0.6): Android activity/view names, Spring annotations and packages,
                         Java GUI component classes
  LICENSE        (-0.6): license headers and warranty-disclaimer words
  EXCEPTIONS     (+0.35): IOException, InterruptedException and similar
  CHAT_TAGS      (-0.3 to +0.3): the <tool_call>, <think> and <tool_response> markup tokens

A token is matched on its text with leading spaces, dots, slashes and parentheses removed,
so ' License', '.License' and '/LICENSE' count as the same word.
"""

READS = ()

SWING_LAYOUT = {
    "GroupLayout", "createParallelGroup", "createSequentialGroup", "addGap",
    "addComponent", "addPreferredGap", "LEADING", "TRAILING", "Alignment",
    "LayoutStyle", "PREFERRED", "BorderLayout", "BorderStyle", "Layout", "setLayout",
}
FRAMEWORK = {
    "onCreate", "savedInstanceState", "Inflater", "LayoutInflater", "Bundle",
    "ViewGroup", "JButton", "JPanel", "JLabel", "jPanel", "jLabel", "stereotype",
    "annotation", "RequestMapping", "factory", "beans", "boot", "permission", "Linq",
    "Generic", "widget", "createElement", "setAttribute",
}
LICENSE = {
    "License", "Licensed", "LICENSE", "licenses", "PROVIDED", "MERCHANTABILITY",
    "WARRANTY", "WARRANTIES", "CLAIM", "FITNESS", "ANY", "DAMAGES", "GNU",
}
EXCEPTIONS = {
    "InterruptedException", "IOException", "SQLException", "PartialEq", "Deserialize",
    "printStackTrace", "Sprintf", "services", "Service",
}
CHAT_TAGS = {
    "<tool_call>": -0.3, "<think>": -0.3, "</tool_call>": -0.2,
    "<tool_response>": 0.2, "</tool_response>": 0.3, "</think>": 0.15,
}


def word_of(token: str) -> str:
    """The token's text without leading spaces, dots, slashes or parentheses."""
    return token.strip().lstrip("./(_")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token.strip() in CHAT_TAGS:
        return carry, CHAT_TAGS[token.strip()]
    word = word_of(token)
    if word in SWING_LAYOUT:
        value = -1.5
    elif word in FRAMEWORK or word in LICENSE:
        value = -0.6
    elif word in EXCEPTIONS:
        value = 0.35
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A lexical detector for English clause-linking constructions.

It emits negative pulses on 'so/such that', predicates introducing 'that',
'that is', 'in order to', 'even though', and a few related idioms. A recent
'so' or 'such' strengthens 'that' across intervening words. The weights are
rounded estimates from training text. They capture large phrase responses,
not the many smaller, word-specific responses. This is not a grammar parser.
"""
import re

READS = ()

# Words introducing propositions, grouped by their ordinary linguistic role.
GUARANTEE = {'ensure', 'ensures', 'ensured', 'ensuring'}
SIGNIFICATION = {'means', 'meaning'}
SUPPOSITION = {'suppose', 'supposes', 'supposed', 'supposing'}
CONDITIONING = {'given', 'assuming', 'considering'}
ASSUMPTION = {'assume', 'assumes', 'assumed', 'assumption', 'assure',
              'assures', 'assured', 'guarantee', 'guarantees'}
SPEECH = {'say', 'says', 'said', 'saying'}
PROPOSITION = {'fact', 'idea', 'condition', 'sense', 'extent', 'provided'}
REQUIREMENT = {'require', 'requires', 'required', 'requiring', 'requirement'}
BELIEF = {'think', 'thinks', 'thinking', 'thought', 'believe', 'believes',
          'believed', 'hope', 'hopes', 'hoped', 'hoping', 'felt', 'consider'}
INFERENCE = {'suggest', 'suggests', 'suggesting', 'implies', 'implying',
             'state', 'states', 'stating', 'indicates', 'indicating'}

THAT_GROUPS = (
    (GUARANTEE | SIGNIFICATION, -1.48), (SUPPOSITION, -1.32),
    (CONDITIONING | {'mean', 'meant'}, -1.10),
    (ASSUMPTION | SPEECH | {'except'}, -0.84),
    ({'sure', 'way', 'because'}, -0.96), (PROPOSITION, -0.73),
    (REQUIREMENT, -0.61), (BELIEF | INFERENCE, -0.48),
    ({'now', 'since', 'thus', 'order'}, -0.82),
    ({'but', 'if'}, -0.46), ({'in', 'as'}, -0.35),
)

# Familiar connective idioms; the pulse is on their second word.
PHRASES = {
    'that is': -0.61, 'that are': -0.28, 'that can': -0.28,
    'that it': -0.28, 'that this': -0.28, 'that case': -0.45,
    'in order': -0.79, 'order to': -0.82, 'order for': -1.0,
    'even though': -1.29, 'even if': -0.94, 'even when': -0.50,
    'so if': -0.35, 'so as': -0.52, 'so it': -0.42,
    'this way': -1.25, 'that way': -1.25, 'either way': -0.80,
    'only way': -0.61, 'way of': -0.48,
    'right now': -0.83, 'for now': -0.83,
    'this reason': -0.83, 'that reason': -0.83,
    'because it': -0.42, 'since it': -0.42,
    'because of': -0.25, 'spite of': -0.48,
    'unless otherwise': -0.50,
}


def response(previous, word):
    p = previous.lower()
    if word == 'that':
        if p == 'so':
            return -2.35 if previous == 'so' else -2.0
        if p == 'such':
            return -1.52
        for group, value in THAT_GROUPS:
            if p in group:
                return value
        return {'that': -0.93, 'for': -0.59, 'and': -0.25,
                ',': -0.19}.get(p, -0.04)
    if word == 'is' and previous in {'That', 'THAT'}:
        return -0.83
    return PHRASES.get(p + ' ' + word,
                       {'order': -0.20, 'way': -0.30,
                        'though': -0.17, 'now': -0.07}.get(word, 0.0))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, recent = ('', '') if first else carry[1:]
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    value = response(previous, word)
    if first and word == 'that':
        value = -0.90 if text.strip()[0].isupper() else -1.31
    elif word == 'that':
        # Degree/result phrases: 'so pleased that', 'such a way that'.
        words = re.findall(r'[A-Za-z]+', recent.lower())
        for distance, cue in enumerate(reversed(words[-4:])):
            if cue in {'so', 'such'}:
                if previous.lower() != cue:
                    strength = 0.65 if cue == 'so' else 0.80
                    if distance == 0:
                        extra = 0.60 if recent.rstrip().endswith(',') else 1.8
                    else:
                        extra = strength / 2 ** (distance - 1)
                    value -= extra
                break

    # Join word fragments, and retain only a short, sentence-bounded tail.
    joined = previous + text
    match = re.search(r'[^\W\d_]+\Z', joined)
    previous = match.group()[-40:] if match else text.strip()
    recent = re.split(r'[.!?;]', recent + text)[-1][-100:]
    return (doc, previous, recent), float(value)

programs.haiku:
"""Layer-0 MLP down-projection, component 68: a 'clause-opening word' detector.

It goes negative on the word that opens a subordinate clause of result, purpose or
reasoning. Strongest on "that" in "so that" (about -2.3), then "that" after "such",
"means", "ensure", "suppose", "given" (about -1.5); moderate on "that" after verbs of
saying or thinking ("said that", "think that", about -0.6); weaker after "but", "and",
"for", "in", "now" (about -0.4). Other "that"s are slightly negative. It also fires on the
"to" of "in order to", the "though" of "even though", the "if" of "even if", and the "is"
of "that is". Everywhere else it is close to zero, and it is never meaningfully positive.
"""

READS = ()

RESULT_BEFORE = {"such", "means", "meaning", "meant", "mean", "ensure", "ensuring",
                 "ensures", "suppose", "supposing", "given", "assuming"}
SAY_BEFORE = {"said", "say", "says", "saying", "assume", "assumed", "think", "thinks",
              "thought", "believe", "claim", "suggest", "suggests", "states", "stated",
              "fact", "hope", "know", "knew", "consider", "conclude"}
WEAK_BEFORE = {"but", "and", "for", "in", "now", "way", "just", "if"}

# Other clause-opening pairs: (word before, word) -> activation.
PAIRS = {
    ("order", "to"): -0.8, ("in", "order"): -0.8, ("even", "though"): -1.3,
    ("even", "if"): -0.9, ("that", "is"): -0.64, ("right", "now"): -0.9,
}


def that_value(prev):
    if prev == "so":
        return -2.3
    if prev in RESULT_BEFORE:
        return -1.5
    if prev in SAY_BEFORE:
        return -0.6
    if prev in WEAK_BEFORE:
        return -0.4
    return -0.1


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if cur == "that":
        return carry, float(that_value(prev))
    if (prev, cur) in PAIRS:
        return carry, float(PAIRS[(prev, cur)])
    return carry, 0.0

programs.luna:
"""Sparse negative cues for English clause-linking phrases.

The clearest responses are in "so/such/means that", "that is", and
"in order to". Other harvested "that" examples follow common clause heads,
so this uses a small word list for that construction and stays quiet elsewhere.
"""
READS = ()

STRONG_HEADS = {
    "so": -2.25,
    "such": -1.47,
    "means": -1.30,
}
OTHER_THAT_HEADS = {
    "assure", "assumption", "assume", "defective", "except",
    "felt", "given", "how", "in", "indicates", "now", "potent",
    "remarking", "require", "say", "sense", "think",
}


def step(carry, prefix, upstream):
    words = prefix.token_strings
    token = words[-1].strip().lower()
    same_document = (
        len(words) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    previous = words[-2].strip().lower() if same_document else ""
    value = 0.0
    if token == "that":
        value = STRONG_HEADS.get(previous, 0.0)
        if not value and previous in OTHER_THAT_HEADS:
            value = -0.70
    elif token == "is" and previous.endswith("that"):
        value = -0.61
    elif token == "order" and previous == "in":
        value = -0.79
    elif token == "to" and previous == "order":
        value = -0.87
    return None, float(value)

programs.sol:
"""Approximate a negative detector of horizontal marks and typographic pauses.

Visible glyphs, repetition length and token spacing set the magnitude.
Newlines, attached letters and bracketed markup usually weaken the response.
Nonbreaking spaces and selected completed Unicode fragments are recognized.
A 24-character tail recognizes LaTeX dot commands and resets at documents.
Other text gets zero: smaller lexical/context effects are not modeled.
"""
import re

READS = ()

# Base magnitude, leading-space bonus, repetition gain, maximum magnitude.
PAUSES = {
    '—': (1.23, 0.21, 2.2, 4.0),
    '…': (0.59, 0.12, 2.3, 3.3),
    '–': (0.10, 0.30, 2.35, 3.3),
    '―': (0.78, 0.00, 2.55, 3.4),
}
# Repetitions beyond this length, gain per extra mark, saturation magnitude.
RUNS = {
    '.': (2, 0.27, 1.5),
    '_': (2, 0.5, 1.8),
    '*': (1, 0.18, 1.3),
    '~': (1, 0.5, 2.0),
    '/': (0, 0.1, 1.3),
    '\\': (3, 0.45, 1.5),
    '·': (1, 0.8, 1.8),
    '・': (2, 0.7, 1.4),
}


def run_strength(char, n, spaced):
    if char == '-':
        return (0.8 if n == 2 else 0.93 if n == 3 else
                1.2 if n <= 32 else 0.65) + 0.2 * spaced
    if char == '=':
        return (0.0 if n == 2 else 0.1 if n == 3 else
                0.7 if n < 16 else 1.4 if n < 32 else 0.9)
    if char == '#':
        return 0.95 if n >= 8 else 0.0
    if char == '+':
        return 1.3 if n >= 4 else 0.0
    if char == '^':
        return min(1.3, 0.13 * (n - 1) ** 2)
    if char in '!?,;':
        return min(1.2, 0.2 * max(0, n - 2))
    if char == '─':
        return 0.53 if n == 1 else 2.35 if n == 2 else 1.8
    if char in '━═':
        return 0.4 if n == 1 else 1.65
    if char in '█¯★':
        return 1.1
    if char == '/' and n < 4:
        return 0.0
    start, gain, cap = RUNS.get(char, (n, 0.0, 0.0))
    return min(cap, gain * max(0, n - start))


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    text = tail + token
    carry = (doc, text[-24:])
    s = token.strip(' \t\r\n')
    spaced = token.startswith(' ')
    strength = 0.0
    for mark, (base, space, gain, cap) in PAUSES.items():
        if mark in s:
            strength = min(cap, base + space * spaced + gain * (s.count(mark) - 1))
            if mark == '…':
                strength += 0.45 * s.count('.')
            if any(c.isalpha() for c in s):
                strength *= 0.72 if mark == '…' else 0.5
            break
    else:
        if s in {'⎯', '┈', '┄', '┅', '┉', '⋯'}:
            strength = 0.75
        elif '\xa0' in s and not s.replace('\xa0', '').strip():
            n = s.count('\xa0')
            strength = 0.07 if n == 1 else min(1.25, 0.22 * n)
        elif s and set(s) <= set('─━═'):
            strength = run_strength(s[0], len(s), spaced)
        else:
            match = re.search(r'([\-\.=_*#+~^/\\·!?,;・─━═█¯★])\1+', s)
            if match and not any(c.isalnum() for c in s):
                run = match.group()
                strength = run_strength(run[0], len(run), spaced and s == run)
                if len(run) > 32 and run[0] in '/_*':
                    strength *= 0.65
    if '<' in s or '>' in s or '[' in s:
        strength *= 0.15
    if token.endswith('�'):
        char = prefix.text_prefixes[-1][-1:]
        if char in {'\u2002', '\u2003', '\x97'}:
            strength = 0.85
        elif char in {'─', '━', '═'}:
            strength = 1.3
    if s in {'dots', 'ots'} and re.search(r'\\[clvh]?dots$', text):
        strength = 0.9
    if '\n' in token:
        strength = max(0.0, strength - 0.65)
    return carry, float(-min(4.0, strength))

programs.luna:
"""Use separator-like glyphs as a cautious cue for negative activations.

Ordinary tokens get zero; recognizable dash, ellipsis, escape, and repeated-mark
tokens get a small estimate because the glyph alone is an imperfect signal.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    mark = token.strip()
    previous = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    value = 0.0

    if token and set(token) == {"\u00a0"}:
        value = -0.48
    elif mark == "—":
        value = -0.3 if "\n" in token else -1.4
    elif mark == "–":
        value = -0.55
    elif mark == "―":
        value = -0.9
    elif mark and set(mark) == {"-"}:
        count = len(mark)
        value = -0.07 if count == 1 else -0.72 if count == 2 else -0.98
    elif mark == "…":
        value = -0.56
    elif mark and set(mark) == {"…"}:
        value = -1.4 * len(mark)
    elif mark.endswith("...") and all(c in ".,;:!?-" for c in mark):
        value = -0.24 if len(mark) > 3 else -0.4
    elif mark and set(mark) == {"."} and len(mark) >= 3:
        value = -0.35
    elif mark == "�":
        value = -1.4 if same_doc and previous == "�" else -0.74
    elif mark and set(mark) == {"\\"} and len(mark) >= 2:
        value = -0.55
    elif mark and set(mark) == {"ー"} and same_doc and previous == "ー":
        value = -0.27

    return carry, float(0.24 * value)

programs.sol:
"""A lexical detector of conditional and comparison markers.

It responds mostly to 'if', 'as', 'without', 'whether', and 'like', and
related words in several languages. Chinese 如 ('as/if') is particularly
strong, even when it occurs in names or other non-conditional uses.
The previous token distinguishes 'such as', 'even if', and desire ('would
like') from resemblance. All unrecognized tokens get zero. State is just
the preceding token, reset at each document boundary.
"""

READS = ()

# Conditional, comparison, and absence words in other languages.
TRANSLATIONS = {
    'wie': 0.93, 'comme': 0.55, 'als': 0.23,
    'như': 2.38, 'zoals': 1.59, 'seperti': 1.61,
    'wenn': 0.38, 'если': 0.32,
    'sans': 0.90, 'ohne': 0.66, 'без': 0.66,
}
CHINESE = {
    # If, supposing, whether, provided that; absence.
    '如果': 1.74, '假如': 1.58, '若是': 1.49,
    '是否': 0.73, '只要': 0.49, '无': 0.73, '無': 0.76,
    # Such as, for example; as follows, how, so, nowadays.
    '比如': 2.68, '例如': 2.06, '诸如': 1.91,
    '如下': 2.51, '如何': 0.78, '如此': 1.49, '如今': 1.58,
    '如有': 4.40, '就像': 1.01, '好像': 0.88,
}
AS_PHRASES = {
    'such': 1.39, 'well': 0.97, 'same': 1.02,
    'long': 1.07, 'far': 1.53, 'soon': 1.32,
    'much': 1.18, 'many': 1.15, 'good': 1.12,
    'known': 0.79, 'seen': 0.84, 'regarded': 0.85, 'described': 0.75,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    lower, prev = word.lower(), previous.strip().lower()
    boundary = token[:1].isspace() or not previous[-1:].isalnum()
    value = 0.0

    if word == '如':
        value = 4.83 if token[:1].isspace() else 6.41
    elif word == '若':
        value = 2.33
    elif word in CHINESE:
        value = CHINESE[word]
    elif word.startswith('如果'):
        pronoun = any(p in word for p in ('你', '您', '我们'))
        value = 1.14 if pronoun else 1.85
    elif '如' in word and len(word) == 2:
        value = 3.10
    elif word in {'_if', '-if', '_as', '.as', '-like', '_like'}:
        value = {'_if': 0.90, '-if': 1.50}.get(word, 0.38)
    elif lower == 'if':
        if word == 'If':
            value = 1.12
        elif word == 'IF':
            value = 0.82
        elif token.startswith('\t'):
            value = 0.99
        else:
            value = 0.70
            value = {'even': -0.03, 'only': 0.10, 'else': 0.31,
                     'as': 0.49, 'so': 0.49}.get(prev, value)
    elif lower in {'elif', 'elseif', 'unless'}:
        value = 0.51 if lower == 'unless' else 0.62
    elif lower == 'as':
        value = AS_PHRASES.get(prev, 0.52) if boundary else 0.03
        if word == 'As':
            value = 0.50
        elif word == 'AS':
            value = 0.21
    elif lower in {'whether', 'without'}:
        value = 0.91 if lower == 'whether' else 1.08
    elif lower == 'like':
        value = 0.60
        if prev in {'would', "'d", '’d'}:
            value = -0.44
        elif prev in {'i', 'you', 'we', 'they', 'really', 'also',
                      'just', 'more', 'much', 'to'}:
            value = 0.0
        elif prev == 'the':
            value = 0.22
        elif prev in {"'t", '’t'}:
            value = -0.30
        elif prev in {'look', 'looks', 'looked', 'sounds', 'things', 'is', 'was'}:
            value = 0.75
        elif prev in {'feel', 'feels', 'felt', 'seem', 'seems', 'seemed'}:
            value = 0.42
        elif prev.endswith('s') and prev.isalpha():
            value = 0.95
    elif lower in TRANSLATIONS and boundary:
        value = TRANSLATIONS[lower]
        if word in {'Wenn', 'Если'}:
            value += 0.22

    return (doc, token), float(value)

programs.haiku:
"""Words meaning "as/like" (comparison, manner, example) or "if/whether/without" (condition).

The component fires on the connective word itself. English "as" and "if" are the
strongest; "as" is strongest in set phrases ("such as", "as far as", "as well as",
"as long as"), and sentence-initial "If" is strong. "even if" / "only if" do not fire,
nor does a verb "like" ("I like", "would like"). Foreign equivalents (wie, comme, sans,
ohne, 如, 若, 例如, ...) also fire.
"""
READS = ()

VALUE = {
    "as": 0.5, "like": 0.6, "if": 0.8, "without": 1.1, "whether": 0.9, "unless": 0.5,
    "wie": 0.9, "comme": 0.6, "sans": 0.9, "ohne": 0.7, "como": 0.5, "wenn": 0.6,
    "如": 6.0, "如果": 1.7, "若": 2.3, "如下": 2.5, "正如": 3.3, "例如": 2.1, "比如": 2.7,
    "如同": 3.1, "犹如": 3.1, "就像": 1.0, "无": 0.7, "無": 0.75, "似": 0.6, "像": 0.4,
}
# the word before "as" that makes it a set phrase: "such as", "as far as", ...
AS_AFTER = {"such": 1.4, "far": 1.5, "well": 1.0, "long": 1.05, "same": 1.0, "soon": 1.3,
            "much": 1.3, "early": 1.5, "good": 1.1}
# words before "if" that make it not a condition ("even if", "only if")
IF_NOT_AFTER = {"even", "only"}
# words before "like" that make it a verb ("I like", "would like")
LIKE_VERB_AFTER = {"would", "i", "not", "t", "to", "you", "we", "they", "just", "who"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    word = raw.lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    value = VALUE.get(word, 0.0)
    if raw in ("If", "Without", "Whether"):
        value *= 1.4
    if word == "as" and prev in AS_AFTER:
        value = AS_AFTER[prev]
    if word == "if" and prev in IF_NOT_AFTER:
        value = 0.0
    if word == "like" and prev in LIKE_VERB_AFTER:
        value = 0.0
    return None, float(value)

programs.sol:
"""Closing quotes and other ending delimiters.

The prediction grows with the token gap since the last quote of the same
family and with the preceding word length, especially when the preceding
token starts with a space. Curly/corner quotes are strongest;
joined punctuation and code brackets weaken the signal. Opening quotes,
contractions and short French/Italian elisions are mostly quiet. Escaped double
quotes have a positive baseline even when opening. Repeated quote characters
get a small fixed response. Bars and comment endings respond weakly.
History resets per document.
"""
import math

READS = ()
KINDS = dict.fromkeys('"“”«»‹›', 'double')
KINDS.update(dict.fromkeys("'‘’", 'single'))
KINDS.update(dict.fromkeys('「」', 'corner'))
KINDS.update(dict.fromkeys('『』《》', 'title'))
ELISIONS = {'l', 'd', 'j', 'c', 't', 'n', 's', 'm', 'qu', 'un'}


def quote_value(s, prev, word, span):
    q = next(c for c in s if c in KINDS)
    i = s.index(q)
    left, right = s[:i], s[i+1:]
    single = KINDS[q] == 'single'
    curly = q in '”»›'
    escaped = q == '"' and left.endswith('\\')
    length = math.log2(max(1, span))
    word_length = math.log2(max(1, len(word)))
    contraction = single and any(c.isalnum() for c in right)
    opening = q in '“‘«‹「『《' or (q in "\"'" and (
        left[:1].isspace() or any(c in left for c in '([{=:') or
        (not left and (not prev.strip() or prev[-1:].isspace() or prev == 'f'))))
    elision = (single and not left and prev.startswith(' ')
               and word.lower() in ELISIONS)
    if contraction or elision:
        return 0.0
    if opening:
        return 0.7 if escaped else 0.0
    space = float(prev.startswith(' '))
    if escaped:
        value = 0.8 + 0.07 * length + 0.23 * word_length
    elif single:
        value = 0.39 + 0.18 * word_length + 0.2 * space
    elif q == '」':
        value = 0.84 + 0.47 * length + 0.2 * word_length
    elif KINDS[q] == 'title':
        value = 0.08 + 0.3 * length
    elif curly:
        value = 0.76 + 0.38 * length + 0.11 * word_length + 0.28 * space
    else:
        value = 0.5 + 0.18 * length + 0.16 * word_length + 0.46 * space
    if any(c in right for c in ')]}'):
        return -0.15 + (0.17 if escaped else 0.09) * length
    if ':' in right:
        return 0.2
    if ',' in right:
        value *= 0.45 if single else (0.75 if curly else 0.6)
    elif ',' in left:
        value -= 1.2 if curly else 0.7
    elif ';' in right:
        value *= 0.4
    elif '\n' in s:
        value *= 0.4 if curly else 0.55
    elif left.strip('\\ ') in ('.', '!', '?', '。', '！', '？'):
        value -= 0.7 if curly else 0.2
    if q in "\"'" and any(c in left + right for c in '<>/*_+=-'):
        return 0.1
    return max(0.0, value)


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, {})
    _, prev, word, position, last = carry
    marks = [c for c in s if c in KINDS]
    value = 0.22 if s.strip() == '|' else 0.0
    if s.strip().startswith('*/'):
        value = 0.5
    if marks:
        kind = KINDS[marks[0]]
        span = min(position - last[kind], 64) if kind in last else 6
        value = quote_value(s, prev, word, span)
        if s.count(marks[0]) > 1:
            value = 0.4 if '\n' in s else 0.1
        for mark in marks:
            if not (KINDS[mark] == 'single' and
                    any(c.isalnum() for c in s[s.index(mark)+1:])):
                last[KINDS[mark]] = position
