"""Approximate a sparse punctuation feature from quote marks and table bars.

It stays quiet on most text, rises on quotation-mark tokens (especially
curly and book-title closing marks), and responds weakly to vertical table dividers.
"""

READS = ()

CLOSERS = '"\'”’»›」』》〉'
TRAILING_PUNCTUATION = '.,!?;:)]}，。！？；：、）'
STRONG_DOUBLE = '”'
STRONG_SINGLE = '’'
CJK_CLOSERS = '»›」』》〉'


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].rstrip()
    # A closing quote may be followed by the sentence's punctuation.
    end = token.rstrip(TRAILING_PUNCTUATION)
    if end and end[-1] in CLOSERS:
        mark = end[-1]
        before = end[:-1]
        previous = ''
        if len(prefix.token_strings) > 1:
            same_doc = (
                prefix.document_ids[-1] == prefix.document_ids[-2]
            )
            if same_doc:
                previous = prefix.token_strings[-2].rstrip()
        previous_is_word = bool(previous) and previous[-1].isalnum()

        if mark in STRONG_DOUBLE:
            return None, 1.60
        if mark in STRONG_SINGLE:
            return None, 0.95
        if mark in CJK_CLOSERS:
            return None, 1.45
        if mark == '"':
            if previous_is_word:
                return None, 0.54
            if previous and previous[-1] in TRAILING_PUNCTUATION:
                return None, 0.08
            if before and before[-1] in TRAILING_PUNCTUATION:
                return None, 0.58
            if before and before[-1].isspace():
                return None, 0.38
            return None, 0.16
        if mark == "'":
            if previous_is_word:
                return None, 0.32
            return None, 0.04
    if '|' in token:
        return None, 0.13
    return None, 0.0

