    elif word.startswith(('publisher', 'export', 'expos', 'explain')):
        value = 0.45
    elif word.startswith(('publish', 'unpublish', 'distribut', 'redistribut')):
        value = 0.75 if word.endswith(('tion', 'tions', 'tor', 'tors')) else 1.3
    elif word.startswith(('announc', 'deploy')):
