STRUCTURES = set('list array tree table grid row column cell collection node '
                 'model view set frame group box stack queue'.split())
PARTS = STRUCTURES | set(
    'item element entry root child parent head tail header footer data source '
    'field index iterator adapter layout container holder count size length '
    'structure type value map'.split())
ORDERING = set('sorted linked ordered unordered nested doubly singly iterable '
               'observable ascending descending sorting'.split())
MODIFIERS = set('current selected selection new create clone temp next previous '
                'each struct custom type data entity component object renderer '
                'linear regression embedded item page map card holder stack '
                'bag grouping'.split())
# Familiar non-collection meanings of otherwise structural words.
OTHER_SENSES = {
    'list': set('price pricing'.split()),
    'tree': set('care line service'.split()),
    'row': set('land lands an ling lett'.split()),
    'grid': set('iron line connected power'.split()),
    'view': set('profile forum memory engine'.split()),
    'cell': set('line death phone cycle surface therapy membrane viability '
                'proliferation'.split()),
    'group': {'therapy'},
    'box': {'office'},
    'data': set('science quality file retention'.split()),
    'array': set('access utils operations real'.split()),
}
BRIDGES = set('of the a an and for to in from is are as on by'.split())


def words(text):
    # Split ASCII identifiers at punctuation and CamelCase boundaries.
    text = re.sub(r'([a-z])([A-Z])', r'\1 \2', text)
    result = []
    for word in re.findall(r'[a-z]+', text.lower()):
        word = {'children': 'child', 'indices': 'index'}.get(word, word)
        if word.endswith('s') and word[:-1] in PARTS:
            word = word[:-1]
        result.append(word)
    return result


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    previous, cue, gap = ('', '', 0) if initial else carry[1:]
    token = prefix.token_strings[-1]
    now = words(token)
    b = now[0] if now else ''
    a = previous
    named = b in PARTS
    value = -0.001
    if b in {'node', 'model'}:
        value += 0.05
    if b in {'adapter', 'iterator', 'header', 'layout'}:
        value += 0.12
    if b == 'view':
        value -= 0.05
    if len(now) > 1 and now[-1] in PARTS:
        value += 0.04
    if initial and b in STRUCTURES:
        value += 0.35 + (0.57 if b in {'list', 'tree'} else 0.0)
    if a in STRUCTURES:
        value += 0.16 if named else (-0.02 if now else 0.0)
    if a in ORDERING and named:
        value += 0.48
    if a in {'binary', 'decision'} and b == 'tree':
        value += 0.34
    if a == 'search' and b == 'tree':
        value += 0.65
    if a in {'tree', 'bst'} and b in {'node', 'model'}:
        value += 0.80
    if a == 'tree' and b in {'data', 'structure'}:
        value += 0.63
    if a == 'data' and b in {'structure', 'model'}:
        value += 0.29
    if a in {'view', 'selection'} and b == 'model':
        value += 0.29 + (0.77 if a == 'selection' else 0.0)
    if a in {'table', 'column'} and b in {'header', 'footer'}:
        value += 0.47
    if a in MODIFIERS and named:
        value += 0.09
    if a in {'list', 'tree', 'grid'} and b in {'item', 'adapter'}:
        value += 0.55
    if a in {'custom', 'type', 'recycler'} and b == 'adapter':
        value += 0.33
    if a in {'child', 'parent'} and b == 'node':
        value += 0.36
    if a == 'array' and b in {'list', 'collection'}:
        value += 0.49
    if b in OTHER_SENSES.get(a, ()):
        value -= 0.45
    if a in {'set', 'array'} and b in {'byte', 'bytes', 'bit', 'bits', 'error'}:
        value -= 0.24
    if a in {'array', 'list'} and b == 'of':
        value += 0.11
    if a in {'tree', 'table', 'grid', 'row', 'column'} and b == 'of':
        value += 0.05
    if a in {'list', 'array', 'tree', 'table', 'sort'} and b == 'the':
        value -= 0.22
    # A brief connective can link a structure to its parts: "list of items".
    if gap in {1, 2} and cue in STRUCTURES and named:
        value += 0.15 if gap == 1 else 0.10
        if cue == 'list' and b == 'item':
            value += 0.20
    if now:
        previous = now[-1]
        if previous in BRIDGES and cue and gap < 2:
            gap += 1
        else:
            cue, gap = (previous, 0) if previous in STRUCTURES else ('', 0)
    else:
        previous, cue, gap = '', '', 0
    return (doc, previous, cue, gap), float(value)

programs.luna:
"""A tiny lexical estimate for sparse collection and interface activations.

Use the near-zero background level, then add a pulse for words naming trees,
lists/items, or common data-model and interface parts.
"""

READS = ()
BASELINE = -0.0007

TREE_WORDS = {"node", "nodes", "tree", "trees"}
LIST_WORDS = {"list", "lists", "item", "items"}
INTERFACE_WORDS = {
    "header", "headers", "footer", "model", "models", "adapter",
    "collection", "collections", "row", "rows", "table", "tables",
    "source", "sources", "hierarchy",
}


def step(carry, prefix, upstream):
    """Add small category-specific pulses to the component's average level."""
    word = prefix.token_strings[-1].strip(" \t\r\n.,;:()[]{}<>`'\"_").lower()
    value = BASELINE
    if word in TREE_WORDS:
        value += 0.08
    elif word in LIST_WORDS:
        value += 0.015
    elif word in INTERFACE_WORDS:
        value += 0.05
    return None, value

"""Approximate a sparse report-and-account vocabulary cue from the current token.

Give report and its inflections a high value, and a short list of record, note,
story, statement, and related action words a smaller one. This is a lexical
shortcut: it ignores context and assigns zero to every other token.
"""

READS = ()

STRONG = {"report", "reports", "reported", "reporting"}
RELATED = {
    "record", "records", "recorded", "recording", "return", "returns",
    "returned", "returning", "note", "notes", "noted", "noting",
    "statement", "statements", "story", "stories", "repeat", "repeated",
    "repeating", "complain", "complains", "complained", "entry", "entries",
}


def step(carry, prefix, upstream):
    word = "".join(ch for ch in prefix.token_strings[-1].lower() if ch.isalpha())
    if word in STRONG:
        return None, 5.5
    if word in RELATED:
        return None, 0.7
