programs.haiku:
"""Words about preferring, choosing, using, and how typical something is.

The component reads the word itself. It is strongest on the verb "prefer" and its kin, then
on other choice verbs and adverbs ("chose", "recommend", "favorite", "often", "likely"),
on "use", and on the "to" right after a choice verb ("prefer to", "chose to"). The value
rises when a frequency word comes just before ("commonly used", "more often"). It is off on
most other words.
"""

READS = ()

PREFER = {"prefer", "prefers", "preferred", "preferably", "preferable", "preference"}
CHOICE = {"favorite", "favourite", "favor", "favour", "choose", "chose", "chosen", "choosing",
          "choice", "pick", "select", "selected", "recommend", "recommended", "recommends",
          "suggest"}
USE = {"use", "used", "uses", "using"}
TYPICAL = {"often", "frequently", "usually", "typically", "commonly", "likely", "probably",
           "mostly", "popular", "expected", "expect", "believe"}
BOOST = {"commonly", "widely", "most", "more", "predominantly", "reliably", "usually",
         "typically", "frequently", "often", "generally", "really"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word == "to" and (before in PREFER or before in CHOICE):
        value = 0.8
    elif word in PREFER:
        value = 2.0
    elif word in CHOICE:
        value = 0.9
    elif word in USE:
        value = 0.8
    elif word in TYPICAL:
        value = 0.65
    else:
        return carry, 0.0
    if before in BOOST:
        value += 0.6
    return carry, value

programs.sol:
"""Approximate a word-piece continuation response, plus chat formatting.

Lowercase Latin/Cyrillic pieces get a length-based boost after another
alphabetic piece of the same script, especially a space-prefixed stem.
The coefficients are fitted averages, not a dictionary of particular words.
The user-role boundary is stronger later in a document than at its start.
State resets at document boundaries; only a short text tail is retained.
"""
from functools import lru_cache
import unicodedata

READS = ()

FORMAT = {
    '<tool_call>': -0.255,
    '</tool_call>': 0.136,
    '<tool_response>': -0.105,
    '</tool_response>': 0.154,
}


@lru_cache(maxsize=8192)
def spelling(s):
    word = s.strip()
    script = None
    if word:
        for name in ('LATIN', 'CYRILLIC'):
            if all(name in unicodedata.name(c, '') for c in word):
                script = name
                break
    return script, len(word), s[:1].isspace(), word[:1].isupper()


def continuation(s, prev):
    script, n, _, _ = spelling(s)
    if not (s.isalpha() and s.islower() and script):
        return 0.0
    pscript, plen, space, capital = spelling(prev)
    same = script == pscript and not prev[-1:].isspace()
    n = min(n, 8)
    length = min(max(plen - 2, 0), 7)
    if script == 'LATIN':
        value = 0.041 - 0.0074 * n - 0.025 * (len(s) == 1)
        if same:
            value += -0.043 + length * (0.017 - 0.0005 * length + 0.011 * n)
            value += space * (0.012 + 0.059 * length) - 0.026 * capital
    else:
        value = 0.132 - 0.038 * n - 0.106 * (len(s) == 1)
        if same:
            value += -0.052 + length * (0.180 - 0.015 * length + 0.001 * n)
            value += space * (0.063 + 0.072 * length) - 0.030 * capital
    return 0.70 * value


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, position, tail = '', 0, ''
    else:
        _, prev, position, tail = carry
        position += 1
    tail = (tail + s)[-32:]
    value = FORMAT.get(s, continuation(s, prev))
    if s == '<|im_start|>':
        value = 0.123 if position == 0 else 0.148 if position < 20 else 0.074
    if s == '<tool_response>' and position < 20:
        value = -0.018
    if s == 'user' and prev == '<|im_start|>':
        value = 1.058 if position == 1 else 1.15 if position < 20 else 1.36
    if tail.endswith('OBSERVATION'):
        if len(tail) == 11 or not tail[-12].isalpha():
            value = 0.138
    return (doc, s, position, tail), float(value)

programs.haiku:
"""Second-piece-of-a-word detector (layer 0, MLP down-projection unit 82).

What it does, in plain terms:
  * The tokenizer splits some words into pieces, e.g. "rhyth|mic", "skirm|ish|ers",
    "melanch|oly", "congrat|ulates". The unit fires on the SECOND piece of such a
    word, more the longer the first piece is:
      - Latin-script words: 0.12 per letter of the first piece beyond 3
        (4 letters -> 0.12, 6 or more -> 0.36);
      - if that second piece is a Latinate word ending (-ation, -ate, -ical, -ian,
        -ist, -ity, -ence, ...), it fires much harder, about 0.8;
      - Cyrillic words: 0.3 after a 3-letter first piece, 0.7 after 4 or more.
  * The role word "user" right after the chat marker "<|im_start|>" gives a
    strong response (about 1.25).
  * Third and later pieces, whole words, punctuation and everything else are 0.

It is a diffuse unit: these rules capture only part of its variance.
"""
import unicodedata

READS = ()

CHAT_ROLE_MARKER = "<|im_start|>"
LATINATE_ENDINGS = {
    "ation", "ations", "lation", "ate", "ates", "ated", "ating", "ator", "ative",
    "ical", "ic", "ial", "ian", "ician", "ist", "istic", "ity", "ality", "ion",
    "ions", "ence", "ance", "ulate", "ulates", "ulated",
}


def _letters(text):
    return len(text) > 0 and all(c.isalpha() for c in text)


def _cyrillic(text):
    return any(unicodedata.name(c, "").startswith("CYRILLIC") for c in text)


def _second_piece(first_len, token):
    """Activation on the second piece of a word whose first piece has first_len letters."""
    if _cyrillic(token):
        return 0.3 if first_len == 3 else (0.7 if first_len >= 4 else 0.0)
    if first_len < 4:
        return 0.0
    if token in LATINATE_ENDINGS:
        return 0.8
    return 0.12 * (min(first_len, 6) - 3)


def step(carry, prefix, upstream):
    # carry: None, or (pieces so far, letters in the first piece) for the current word.
    t = prefix.position
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        carry = None
    token = prefix.token_strings[t]
    previous = prefix.token_strings[t - 1] if t > 0 else ""
    if token == "user" and previous == CHAT_ROLE_MARKER:
        return None, 1.25
    if not _letters(token.strip()):
        return None, 0.0
    if token[:1] != " " and carry is not None:
        pieces, first_len = carry
        if pieces == 1:
            return (2, first_len), _second_piece(first_len, token)
        return (pieces + 1, first_len), 0.0
    return (1, len(token.strip())), 0.0

programs.luna:
"""Approximate a small code-naming feature.

The component tends to pulse when a token begins a name after a function
signature, a type, or a declaration/path marker. Return a typical pulse for
those contexts and leave other tokens at zero.
"""
READS: tuple[str, ...] = ()

FUNCTION_MARKERS = {"def", "fn", "func", "function", "void"}
TYPE_WORDS = {
    "int", "float", "double", "char", "String", "string",
    "bool", "boolean", "long", "short", "byte", "auto",
    "usize", "isize", "i8", "u8", "i16", "u16", "i32", "u32",
    "i64", "u64", "f32", "f64", "size_t",
}
DECLARATION_PULSES = {"const": 0.55, "let": 0.15, "var": 0.15}


def step(carry, prefix, upstream):
    if prefix.position == 0:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0

    name = prefix.token_strings[-1].lstrip()
    if not name or not (name[0].isalpha() or name[0] in "_$"):
        return None, 0.0

    marker = prefix.token_strings[-2].strip()
    if marker in FUNCTION_MARKERS:
        return None, 1.5
    if marker in TYPE_WORDS:
        return None, 0.6
    if marker in DECLARATION_PULSES:
        return None, DECLARATION_PULSES[marker]
    if marker == "import":
        return None, 0.24
    if marker == "::":
        return None, 0.34
    return None, 0.0

"""Give a small positive score to labels seen in book and study contexts."""

READS = ()

RESOURCE_LABELS = {
    "reader", "readers", "topic", "topics",
    "edition", "editions", "isbn",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    return None, 0.06 if word in RESOURCE_LABELS else 0.0

programs.haiku:
"""Layer-0 MLP unit 88 (writes into the residual stream via down_proj).

What it does, in plain terms: it is a sparse "code and test-log" detector. It is near
zero on ordinary prose and fires on a few formulaic tokens in software text:
  * Go/test-runner output: the word RUN, FAIL or PASS right after a "===" or "---"
    marker ("=== RUN   TestFoo", "--- PASS: TestBar"). These are the strongest.
  * The chat reasoning tag "<think>" (mostly right after a newline).
  * The first word after a URL scheme, a dunder "__", or a "#[" / "[#" / "<!--" opener
    ("https://github", "def __init__", "#[derive").
  * A handful of software-project words (github, repo, init, router, json, config, ...),
    weakly.
  * Second words of some place names ("New York", "United States", "San Francisco") and
    a few Java/library names (.java, Utils, Exception), where it dips slightly negative.

Everything else predicts 0. Values are the typical activation for each case.
"""
READS = ()

TEST_WORDS = {"RUN", "FAIL", "PASS"}
TEST_MARKERS = {"===", "---"}
OPENERS = {"://", " __", "#[", "[#", "<!--"}
SOFTWARE = {"github", "repo", "init", "summary", "router", "json", "config", "main", "node",
            "python", "tests", "install", "version", "License", "LICENSE", "README", "run", "grep"}
PLACE_SECOND_WORDS = {"York", "States", "Francisco", "Angeles", "Africa", "Rico"}
JAVA_NAMES = {".java", "Utils", "-utils", ".util", ".api", "Exception", "Args"}


def step(carry, prefix, upstream):
    """Predict this unit's activation at the newest token of the prefix."""
    token = prefix.token_strings[-1]
    word = token.strip()
    before = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    before_raw = prefix.token_strings[-2] if len(prefix) > 1 else ""

    if word in TEST_WORDS:
        value = 3.0 if before in TEST_MARKERS else (1.0 if word != "PASS" else 0.3)
    elif token == "<think>":
        value = 1.6
    elif before_raw in OPENERS:
        value = 1.0
    elif word in SOFTWARE:
        value = 0.4
    elif word in PLACE_SECOND_WORDS or token in JAVA_NAMES:
        value = -0.4
    else:
        value = 0.0
    return None, float(value)

"""Commerce / merchant word detector (layers.0.mlp.down_proj:89).

A negative detector for words about trade and merchants. It dips hardest on the
Chinese character 商 (shang, "trade/merchant", as in 商人, 商业, 特许经营商), and
moderately on the English words "commercial", "commerce" and "merchant(s)".
Everything else is predicted as 0. It looks only at the current token.
"""

READS = ()

TRADE_CHAR = "商"
ENGLISH_TRADE = ("commerc", "merchant")   # commerce, commercial, merchant(s)


def value(token: str) -> float:
    if token.strip() == TRADE_CHAR:
        return -6.4
    if TRADE_CHAR in token:
        return -2.0
    low = token.lower()
    if any(stem in low for stem in ENGLISH_TRADE):
        return -1.8
    return 0.0


def step(carry, prefix, upstream):
    return None, float(value(prefix.token_strings[-1]))

