"""Recognize tab-based source indentation and estimate its activation by width."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if not token.startswith("\t"):
        return None, 0.0

    spaces = token[1:]
    if not spaces or any(char != " " for char in spaces):
        return None, 0.0

    width = len(spaces)
    if width <= 3:
        value = 2.25
    elif width <= 5:
        value = 2.6
    elif width <= 9:
        value = 2.15
    elif width <= 15:
        value = 1.85
    else:
        value = 1.5
    return None, value

programs.sol:
"""A lexical approximation of speech/thought reporting, and academic help.

'thought' is strongest, then 'says'; other inflections have separately
calibrated strengths.  The preceding word distinguishes 'United States'
from reporting what a text states, and 'I think' from modal/infinitive
uses.  'To say' is weaker than attributing speech to people or reports.
Chinese and Japanese reporting/thought words get positive values too.
Academic assistance words are negative, especially 'homework help'.
This models selected strong lexical responses, not general understanding
of reported speech; weaker responses to other words are omitted.
Unrecognized tokens are left near zero, not modeled individually.
"""

READS = ()

# These are literal inflections, not a general list of synonyms.
THOUGHT = {
    'thought': 1.00, 'thoughts': 0.72, 'thinking': 0.56,
    'thoughtful': 0.33,
    'thinks': 0.46, 'think': 0.25,
}
REPORTING = {
    'says': 0.83, 'said': 0.51, 'say': 0.52, 'saying': 0.40,
    'states': 0.36, 'state': 0.14, 'stated': 0.10,
    'wrote': 0.45, 'write': 0.12, 'writes': 0.24, 'written': 0.15,
    'mentions': 0.23, 'told': 0.11, 'reported': 0.09,
}
EAST_ASIAN = {
    '说': 0.53, '說': 0.39, '我说': 0.39,
    '思': 0.53, '思想': 0.46, '思考': 0.31,
    '称': 0.43, '稱': 0.28, '表示': 0.19, '显示': 0.46,
    '载': 0.43, '載': 0.49, '认为': 0.13, '他说': 0.41,
}
TEXT_SOURCES = {
    'problem', 'question', 'description', 'report', 'reports',
    'article', 'law', 'theorem', 'statement', 'letter', 'bible',
}
SPEAKERS = {
    'police', 'officials', 'authorities', 'experts', 'researchers',
    'scientists', 'people', 'they',
}
# A separate negative response to academic help and assistance vocabulary.
ASSISTANCE = {
    'homework': -0.21, 'essay': -0.35, 'calculator': -0.29,
    'assistance': -0.20, 'support': -0.07, 'services': -0.13,
    'writing': -0.10, 'paper': -0.11, 'papers': -0.11,
    'tutor': -0.55, 'tutors': -0.55, 'tutoring': -0.55,
}
MODALS = {'can', 'could', 'would', 'will', 'may', 'might', 'should'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    previous = ''
    if len(prefix.token_strings) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2].strip()
    prev = previous.lower()
    value = THOUGHT.get(
        lower, REPORTING.get(lower, ASSISTANCE.get(lower, 0.002)))
    if word in EAST_ASIAN:
        value = EAST_ASIAN[word]
    elif lower == 'help':
        value = -0.07
        if prev == 'to':
            value = 0.14
        elif prev in {'need', 'seeking'}:
            value = -0.25
        elif prev in {'homework', 'essay', 'assignment', 'math', 'textbook'}:
            value = -1.20
            if prev == 'assignment':
                value = -1.65
            if word == 'Help' and previous in {'Homework', 'Assignment'}:
                value = -2.35
    elif lower == 'helper' and prev in {'homework', 'assignment'}:
        value = -0.95
    elif lower == 'think':
        if prev.strip('“”"') == 'i':
            value = 0.09
        elif prev == 'to':
            value = 0.36
        elif prev in MODALS:
            value = 0.48
        elif prev == 'you':
            value = 0.20
    elif lower == 'states':
        if prev == 'united':
            value = 0.0
        elif word != 'states':
            value = 0.14
        elif prev in TEXT_SOURCES or prev == 'it':
            value = 0.70
    elif lower == 'says' and (prev in TEXT_SOURCES or prev == 'it'):
        value = 1.00
    elif lower == 'say':
