programs.sol:
"""A negative phi/ph detector, strongest on letters and short word fragments.

Longer ph-initial words are weaker; incidental ph deep inside words is ignored.
Related ph/f spellings and Chinese translations of Greek-derived terms
also respond. Recent Greek text distinguishes phi in prose from math notation.
"""
import string

READS = ()

# Root, response to the bare root, response to a longer word beginning with it.
PH_ROOTS = (
    ('phosph', 1.9, 1.45),
    ('phase', 1.55, 1.15),
    ('phil', 2.3, 1.35),
    ('phot', 1.65, 0.8),
    ('phon', 1.25, 0.65),
    ('phen', 1.8, 0.85),
    ('phys', 1.1, 0.85),
    ('phr', 1.0, 1.0),
)
# Short ph/f renderings across scripts, including foreign-name syllables.
F_SPELLINGS = {
    'フィ': 1.6,
    'フェ': 1.6,
    'ファ': 1.1,
    'フォ': 0.6,
    'フ': 0.45,
    '프': 1.4,
    '파': 1.4,
    'फ': 0.9,
    '菲': 4.0,
    '斐': 1.6,
}
PH_TRANSLATIONS = {
    '哲学': 2.5,  # philosophy
    '哲學': 2.5,
    '哲': 1.6,  # wisdom / philosophy word fragment
    '物理': 1.3,  # physics
    '酚': 2.4,  # phenol
    '相': 0.75,  # phase (also has other meanings)
}


def latin_strength(s, recent):
    word = s.strip(string.whitespace + string.punctuation)
    w = word.lower()
    if w == 'ph':
        if word == 'pH':
            return 1.1
        if word == 'Ph' or s.startswith(('.', '-')):
            return 2.4
        if word == 'PH':
            return 1.75
        if s.startswith(' '):
            return 1.7
        return 0.7 if recent.lower().endswith('m') else 1.3
    if w == 'phi':
        return 2.65
    if w == 'php':
        return 2.3
    if w == 'phd':
        return 1.45
    if w == 'iphone':
        return 0.7
    if w in ('pha', 'phe', 'phy'):
        return 1.45
    for root, short, long in PH_ROOTS:
        if w.startswith(root):
            if w.startswith('philosoph'):
                return 1.8
            if w in ('photo', 'photon', 'physics'):
                return 1.1
            return short if w == root else long
    if w.startswith('ph'):
        return 0.7
    if w.startswith('oph') and len(w) <= 5:
        return 1.5
    if w.endswith('ph') and len(w) <= 4:
        return 0.85 if w.startswith(('i', 'ro')) else 0.4
    if w.startswith('profile'):
        return 0.85
    if w == 'fil':
        return 0.85
    if w.startswith(('filename', 'filament')):
        return 0.55
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    recent = '' if reset else carry[1]
    s = prefix.token_strings[-1]
    split = '\ufffd' in s
    if split and not reset:
        # Decode a completed Unicode character rather than a lone byte fragment.
        completed = prefix.text_prefixes[-1][-1:]
        if completed != '\ufffd':
            s = completed
    w = s.strip()
    if any(c in s for c in 'φϕΦ'):
        greek = sum('\u0370' <= c <= '\u03ff' or '\u1f00' <= c <= '\u1fff'
                    for c in recent)
        if 'Φ' in s:
            strength = 4.9 if split else 3.3
        elif 'ϕ' in s:
            strength = 3.4
        else:
            strength = 5.1 if greek >= 8 else 3.0
    elif 'ф' in s.lower():
        if w in ('ф', 'Ф'):
            strength = 3.55 if s.startswith(' ') or w == 'Ф' else 2.0
        elif w.lower() in ('фи', 'фото', 'оф'):
            strength = 1.4
        else:
            strength = 0.35 if len(w) <= 4 else 0.1
    elif w == 'フ' and split:
        strength = 2.95
    elif w in F_SPELLINGS:
        strength = F_SPELLINGS[w]
    elif 'ف' in w and len(w) <= 3:
        strength = 1.3 if w == 'الف' else (0.75 if s.startswith(' ') else 0.3)
    elif w in PH_TRANSLATIONS:
        strength = PH_TRANSLATIONS[w]
    else:
        strength = latin_strength(s, recent)
    return (doc, (recent + s)[-40:]), float(-strength)

