programs.sol:
"""A detector for selected relation words, especially for/from and 对/對.

Training spikes concentrate on these spellings, motivating lexical rules.
English forms get moderate signals, altered in a few verb+for phrases.
The Sino-Japanese 'toward' character gets a strong signal, smaller in
lexicalized compounds. These are lexical rules, not general relation parsing.
A short multilingual word list covers other related prepositions.
Unmatched tokens return zero; small background lexical variation is omitted.
"""
READS = ()

RELATION_WORDS = {
    'für': 1.25, 'för': 0.95, 'från': 0.55, 'voor': 0.84,
    'para': 0.67, 'pour': 0.23, 'для': 0.68, 'đối': 3.8,
    'relative': 1.35, 'relatively': 0.58, 'opposite': 0.44,
    'dafür': 1.42, 'gegenüber': 1.17, 'dla': 1.17,
    '대': 3.0, '대한': 1.76, '대해': 1.43,
    'に対': 5.7, 'に対して': 1.7, '対': 8.2, '在': 1.2,
    '为': 0.55, '為': 0.55, '从': 0.6, '從': 0.6,
    '把': 0.85, '通过': 0.9, '通過': 0.8, '将': 0.6, '將': 0.6,
    '向': 0.5, '给': 0.6, '給': 0.6, '关于': 1.3, '關於': 1.3,
}
ENGLISH_FORMS = {
    'for': 1.0, 'For': 1.4, 'FOR': 1.2,
    'from': 1.0, 'From': 1.35, 'FROM': 0.9,
}
# These contain 对 but mean objects, opposition, comparison, etc.
LEXICALIZED = {
    '对象', '对应', '对照', '对方', '对接', '对比', '对话',
    '对抗', '对标', '对决', '反对', '绝对', '针对性',
    '对付', '对策', '对阵', '面对面', '竞争对手', '对外开放',
}
# Directed at, responding to, facing, relative to, treating.
FACING = {'针对', '应对', '面对', '相对', '对待'}
TRADITIONAL = str.maketrans('對於針應絕話標決', '对于针应绝话标决')


def response(token, previous=''):
    word = token.strip()
    bare = word.lstrip('._(-/—#')
    if bare in ENGLISH_FORMS:
        value = ENGLISH_FORMS[bare]
        if bare != word or '\t' in token:
            value = 1.7 if bare.lower() == 'for' else 1.2
        elif not token.startswith(' '):
            value += 0.2
        if token == ' for':
            p = previous.strip().lower()
            if p in {'look', 'looking'}:
                value = -0.35
            elif p in {'account', 'accounting', 'solve', 'solving'}:
                value = 0.1
            elif p in {'ask', 'asks', 'asked', 'asking', 'searching'}:
                value = 0.28
        return value
    if word.lower() in {'foreach', 'forall'}:
        return 1.6
    relation = word.lstrip('，').lower()
    if relation in RELATION_WORDS:
        return RELATION_WORDS[relation]
    simple = word.translate(TRADITIONAL)
    if '对' in simple:
        if simple == '对':
            return 6.6 if token.startswith(' ') else 8.4
        if any(w in simple for w in LEXICALIZED):
            return 1.5
        if any(w in simple for w in FACING):
            return 3.6
        if '对于' in simple:
            return 5.6
        if simple in {'对手', '对面', '对不起', '一对一', '对立'}:
            return 2.8
        if simple in {'对着', '对我说', '对外'}:
            return 4.5
        if simple in {'一对', '不对', '对此'}:
            return 6.3
        return 7.5
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = ''
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
    # Recognize 対 even when the current token is only its final UTF-8 byte.
    if '\ufffd' in token and prefix.text_prefixes[-1].endswith('対'):
        token = '対'
    return None, float(response(token, previous))

