"""Fires on prepositions that introduce a target, beneficiary or source, above all the
English words "for" and "from" (and their spellings), the equivalents in other languages,
and most strongly the Chinese word 对 / 對 ("toward, to, for, regarding") and its
compounds. Its predicted activation depends only on the current token."""

READS = ()

# English "for" and "from", in the spellings a token can take
FOR_WORDS = {" for": 1.0, "for": 1.4, " For": 1.4, "For": 1.5, "\tfor": 1.8, " FOR": 1.1, "_for": 1.9,
             "_FOR": 1.6, "-for": 1.6, "forall": 1.4, " foreach": 1.8}
