# Chinese 对 / 對 ("toward, to, for, regarding") and its compounds: the strongest of all
TOWARD = {"对": 8.7, "對": 8.5, " 对": 6.5, "对于": 5.2, "这对": 7.8, "一对": 6.2, "对我": 6.0,
          "这对于": 6.0, "对着": 4.0, "针对": 3.4, "面對": 3.3, "对接": 1.5, "反对": 1.3}

# Korean 대 / 대한 (for, about)
KOREAN = {"대": 2.6, " 대": 3.1, " 대한": 1.8}

VALUES = {**FOR_WORDS, **FROM_WORDS, **OTHER_PREPOSITIONS, **TOWARD, **KOREAN}


