programs.sol:
"""Predict teen-number pairs and a separate 'life' vocabulary response.

A digit immediately following 1 activates strongly for 12--19, peaking near
15--18. These pairs count inside longer numbers too. Repeated 1 strengthens
the response; larger preceding digits weaken it. A decimal point, comma,
or space between the digits weakens it further. Fullwidth decimal digits
are treated like ordinary digits. Life-related words give a smaller positive
response, increased for several life-stage and social modifiers. Ordinal
suffixes and punctuation immediately after 1 receive negative predictions.
Only the previous two tokens are remembered, resetting at document changes.
"""
READS = ()

DIGIT_STRENGTH = (-0.06, 0.09, 0.76, 1.25, 1.47,
                  1.63, 1.65, 1.69, 1.61, 1.49)
LIFE_WORDS = {
    'life': 1.00, '-life': 0.83, 'lives': 0.54,
    'lifetime': 0.23, 'lifespan': 0.44, 'lifestyle': 0.30,
    'vida': 0.45, 'vie': 0.18, 'жизнь': 0.44, 'жизни': 0.44,
    '生命': 0.64, '命': 0.58, '生活': 0.50, '生活中': 0.70,
}
LIFE_STAGE_OR_SOCIAL = {
    'early', 'adult', 'american', 'christian', 'modern',
    'civilian', 'greek', 'family',
}
PERSONAL_OR_DAILY = {
    'personal', 'private', 'daily', 'everyday', 'political',
    'spiritual', 'school', 'later',
}


def digit(token):
    return int(token) if len(token) == 1 and token.isdecimal() else None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous, before = ('', '') if carry is None or carry[0] != doc else carry[1:]
    value = -0.001
    d, p, b = digit(token), digit(previous), digit(before)
    if d is not None:
        if p == 1:
            value = DIGIT_STRENGTH[d]
            if b == 1:
                value *= 1.14
            elif b is not None and b >= 2:
                value *= 1.0 - 0.02 * b
        elif b == 1 and previous in ('.', ',', ' '):
            value = DIGIT_STRENGTH[d] * {'.': 0.33, ',': 0.16, ' ': 0.20}[previous]
        elif p is not None and p >= 2 and d == 1:
            value = -0.08
    else:
        word, prior = token.strip().lower(), previous.strip().lower()
        value = LIFE_WORDS.get(word, value)
        if word in ('life', '-life'):
            if prior == 'real':
                value = 0.65
            elif prior in ('my', 'your', 'her', 'his', 'its'):
                value = 0.90
            elif prior in LIFE_STAGE_OR_SOCIAL:
                value = 1.55
            elif prior in PERSONAL_OR_DAILY:
                value = 1.28
        elif word == 'of' and prior in ('life', '-life'):
            value = 0.44
        if p == 1:
            if token in ('st', 'th'):
                value = -0.43 if token == 'st' else -0.22
            elif token in ('.', ','):
                value = -0.06
    return (doc, token, previous), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:98 -- a "recency / nearness" detector.

This component writes a strong signal for words that mean "recent" or "near in
time or space". Its activation is:
- large on "recent" and "recently" (about 4.8), and on the Chinese 近 (near, recent),
  which covers 最近 "recently", 近期, 近年来 (about 6);
- moderate on the nearness words "nearest", "nearly", "near", "closest", "close",
  "adjacent", "approach", "latest", "newly", "modern", "almost" (about 1);
- weak on the "just now / soon / recent past" words "just", "over", "least", "past",
  "soon", "shortly", "late", and on Chinese 今, 前, 就, 过去 (about 0.7);
- negative, about -1.3, on <|endoftext|>, the document boundary token.
Everything else sits near zero. The program looks only at the newest token.
"""

READS = ()

RECENT = {"recent", "recently"}
NEAR = {"nearest", "nearly", "near", "closest", "closely", "close", "adjacent",
        "approach", "approaches", "approaching", "approached", "newly", "latest",
        "almost", "modern"}
NEAR_ZH = {"接近", "靠近", "迩", "不久前"}
JUST = {"just", "over", "least", "past", "soon", "shortly", "late"}
JUST_ZH = {"今", "前", "就", "过去"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = s.strip().lower()
    if s == "<|endoftext|>":
        value = -1.3
    elif "近" in s:
        value = 6.0
    elif w in RECENT:
        value = 4.8
    elif s in NEAR_ZH:
        value = 2.5
    elif w in NEAR:
        value = 1.0
    elif w in JUST or s in JUST_ZH:
        value = 0.7
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Approximate the component's dominant colon/value-boundary response.

Closing quotes plus a colon are strongest; brackets and Markdown endings
are weaker. Bare-colon estimates grow with line length and shrink with
document depth, indentation, preceding digits or capitals, repeated colons,
tool output, and reply/warning/Q&A labels. Other tokens default to zero.

State resets between documents and retains at most 400 characters of the
current line, treating escaped newlines as line breaks. Small, unrelated
word-specific responses are deliberately not modeled.
"""
READS = ()


def punctuation_value(token):
    if token.endswith(':'):
        before = token[:-1]
        if before and set(before) <= set('"”'):
            return 1.13
        if before in ("'", '’'):
            return 1.01
        if before == '`':
            return 0.88
        if before and set(before) <= set('\\"\''):
            return 0.90
        if before.strip() and set(before.strip()) <= set('()]}?>"\''):
            return 0.52
        if before and set(before) <= set('*_'):
            return 0.37
        if before == '.':
            return 0.58
        if before.isspace():
            return 0.08
    if token in ('":"', "':'"):
        return 0.27
    if token == '":[':
        return 0.52
    if token in ('":\n', "':\n"):
        return 0.28
    if token in (':\n', ':\n\n'):
        return -0.06
    if token in (':"', ":'", '://', ':/'):
        return -0.13
    if token == '::':
        return -0.04
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, False)
    _, line, previous, position, tool_output = carry
    token = prefix.token_strings[-1]
    value = punctuation_value(token)
    if token == ':':
        word = previous.strip()
        length = len(line)
        value = 0.40 + 0.52 * length / (length + 40)
        value -= 0.37 * position / (position + 20)
        value += 0.09 * previous.startswith(' ')
        value -= 0.19 * word[-1:].isdigit()
        value -= 0.07 * word.isupper()
        value -= 0.17 * (len(line) - len(line.lstrip()) >= 2)
        value -= 0.08 * min(line.count(':'), 4)
        value -= 0.08 * tool_output
        if word.lower() == 're':
            value -= 0.39  # Reply/email subject prefix.
        elif word.lower() in ('note', 'warning', 'error'):
            value -= 0.20
        elif word.lower() in ('q', 'a'):
            value -= 0.10
    if '<tool_response>' in token:
        tool_output = True
    elif '</tool_response>' in token:
        tool_output = False
    line = (line + token).replace('\\n', '\n').split('\n')[-1][-400:]
    return (doc, line, token, position + 1, tool_output), float(value)

programs.haiku:
"""Colon detector: how strongly a colon token fires depends on what comes before it.

Fires on colons that introduce a phrase, a title, a list or an explanation
(`...the following points:`, `Mission Statement:`, `"name": ...`).
"""
READS = ()

CODE_CHARS = set("{}()=;")


def _line_before(strings):
    """Text on the current line before the newest token."""
    parts = []
    for t in reversed(strings[:-1]):
        if "\n" in t:
            parts.append(t.split("\n")[-1])
            break
        parts.append(t)
        if len(parts) > 40:
            break
    return "".join(reversed(parts))


def step(carry, prefix, upstream):
    s = prefix.token_strings
    cur = s[-1]
    if cur == ":":
        prev = s[-2] if len(s) > 1 else ""
        if not prev[-1:].isalpha():
            return None, 0.0  # colon after a digit, as in 10:30
        words = _line_before(s).split()
        value = 0.1 + 0.05 * min(len(words), 6)
        if CODE_CHARS & set(_line_before(s)):
            value -= 0.15  # code-like line
        return None, value
    if cur == " :":
        return None, 0.07
    if cur in ('":', "':", '\\":', "`:"):
        return None, 1.1  # colon after a closing quote: JSON-like keys
    if cur.endswith(":") and len(cur) > 1 and cur != "::":
        return None, 0.5  # colon after a closing bracket, e.g. "):" or "**:"
    return None, 0.0

programs.sol:
"""A small lexical model, not a general topic detector.

Evidence, suspects, dead bodies, and several inference/possibility words
receive negative values; active inquiry, patterns, and support receive positive
ones. A few grammatical, code, and conversation-marker classes capture weaker
responses. Document starts and the immediately preceding grammatical word
modify some responses. Training responses differed even between synonyms,
so these are deliberately selected word forms, not whole semantic fields.
Everything else is approximated as zero; most lexical variation is not modeled.
"""
READS = ()

SUSPECTS = frozenset('suspect suspects suspected'.split())
SUSPICION = frozenset('suspicion suspicions suspicious 怀疑 嫌疑 嫌疑人'.split())
