    (SUSPECTS, -0.27), (SUSPICION, -0.08),
    (FORENSIC_NOUNS, -0.32), (DEAD_OR_MURDER, -0.20),
    (EVIDENCE, -0.13), (DISCOVERY, -0.055), (INFERENCE, -0.067),
    (POSSIBILITY, -0.045), (LIKELIHOOD_ADJECTIVES, -0.105),
    (INQUIRY, 0.115), (PATTERNS, 0.105), (TRAILS, 0.18),
    (AFFIRMATION, 0.07), (NEGATION, -0.045), (EXCLUSION, -0.07),
    (ALTERNATIVES, -0.035), (MAKING, 0.045), (WANTING, 0.05),
)
ARTICLES = frozenset('a an the'.split())
BE = frozenset("am is are was were be been being 'm 're ’m ’re".split())
PRONOUNS = frozenset('i we you he she they'.split())
MARKERS = {
    '<tool_response>': 0.053,
    '</tool_response>': -0.045,
    '</tool_call>': 0.048,
    '</think>': -0.076,
}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    spelling = token.strip()
    word = spelling.lower()
    value = 0.0
    continuation = (
        not first and not token[:1].isspace()
        and carry[2] and word.isascii() and word.isalpha()
    )
    if not continuation:
        for words, response in LEXICAL:
            if word in words:
                value = response
                break

    if not first and not continuation:
        if word in {'suspect', 'suspects'}:
            if previous in ARTICLES:
                value = -0.48
            elif previous in PRONOUNS:
                value = -0.15
        if word in INQUIRY and previous in BE:
            value += 0.05
        if word == 'evidence':
            if previous in ARTICLES | {'no', 'any'}:
                value -= 0.065
            elif previous in {'empirical', 'supporting', 'scientific', 'strong'}:
                value = 0.0
            elif previous == 'dna':
