        if word in {'found', 'discovered'}:
            if previous in {'study', 'studies', 'researchers', 'health', 'results'}:
                value = 0.07
            elif previous in {'not', 'never'}:
                value -= 0.085
            elif previous in {'i', 'we', 'have', 'has', "'ve", '’ve'}:
                value += 0.045
