            value = -0.70  # Beginning of 碎尸万段: dismemberment.

    if first:
        if word in {'clue', 'discovered', 'gefunden', 'suspicions'}:
            value = -0.67
        elif word in EVIDENCE:
            value = -0.50
        elif word in DISCOVERY:
            value = -0.40
        elif word == 'likely':
            value = -0.44
        elif word == 'probably':
            value = -0.24
        elif word in INQUIRY:
            value = -0.14
        elif word in AFFIRMATION:
            value = 0.0
        if spelling.istitle():
            value *= 0.65
    elif value and spelling.istitle():
        value *= 0.75

    if word == 'gefunden' and not first:
        value = -0.19  # German: found.
    if word == '.metamodel':
        value = 0.68  # Java persistence metamodel package.
    if token in MARKERS:
        value = MARKERS[token]
    if token in {' import', '\tfrom', '#include'}:
        value = -0.085
    if token == '\\n':
        value = -0.033
    if token == ',':
        value = 0.004
    if spelling.isdecimal() and spelling.isascii():
        value = -0.004
    if first:
        # With no preceding context, formatting tokens have distinct responses.
        if token.isspace():
            value = 0.065 if '\n' in token else -0.085
        elif token.startswith('#'):
            value = -0.13
        elif token == '<|im_start|>':
            value = 0.046
        elif token == '<|endoftext|>':
            value = 0.124
        elif word == 'other':
            value = 0.04
        elif word == 'know':
            value = -0.013
        elif word == 'confirmed':
            value = -0.44
        elif spelling.isdecimal():
            value = 0.0
    return (document, word, token[-1:].isalpha()), float(value)

