"""A small lexical proxy for investigation and identification language.

Evidence, suspicion, crime, and uncertainty words get a small negative estimate;
words for looking, recognizing, or identity get a small positive one. The
component's remaining context-sensitive variation is left at zero.
"""
READS = ()

EVIDENCE_AND_UNCERTAINTY = frozenset({
    "evidence", "clue", "hint", "suspect", "suspected", "suspicion",
    "stranger", "unlikely", "likely", "unknown", "possibly", "explanation",
    "believe", "confirmed", "crime", "police", "murder", "dead", "corpse",
    "尸", "gefunden", "found", "discovered",
})
IDENTIFICATION = frozenset({
    "looking", "identity", "identities", "identify", "recognized",
    "recognised", "discovering", "現場", "现场",
})


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word in EVIDENCE_AND_UNCERTAINTY:
        return None, -0.08
    if word in IDENTIFICATION:
