STATIVE = set('called known considered related involved limited interested '
              'aware identical proportional classified composed subjected '
              'constrained willing entitled responsible divisible bound '
              'scattered accused implicated licensed owned ashamed '
              'affiliated structured'.split())
RELATIONS = set('associated named capable subject similar prone akin alike'.split())
DESCRIPTIONS = set('available born designed described determined unable '
                   'concerned connected characterized represented identified '
                   'listed distributed awarded supported suitable confident '
                   'equivalent valid compatible sold regarded'.split())
ACTION_PARTICIPLES = set('changed increased returned moved put cut helped met '
                        'reached received turned find help'.split())
COMPLETED_ACTIONS = set('done made taken seen added performed'.split())
ADVERBS = {
    'still': -1., 'currently': -1.05, 'originally': -1.05,
    'now': -0.85, 'also': -0.3, 'often': -0.3, 'never': 1.,
    'here': -0.6, 'there': -0.6, 'somewhere': -1.4, 'anywhere': -1.4,
}
FUNCTION_WORDS = {
    'being': 1.1, 'to': 0.23, 'as': -0.75, 'had': 1.85,
    'will': 1.5, 'has': 1.3, 'ist': 1.7, 'become': 1.5,
    'no': -0.3, 'any': -0.3, 'all': -0.65, 'both': -1.05,
    'either': -1.05, 'one': -0.45, 'part': -0.9, 'most': -0.45,
    'nothing': -0.65, 'something': -0.45, 'anything': -1.05,
    'this': 0.45, 'these': 0.45, 'those': 0.45,
    '': -0.12, ',': 0.3,
}


def complement(word):
