        if word in values:
            return values[word]
    if word in {'based', 'located', 'guilty'}:
        return -1.8
    if word in RELATIONS:
        return -1.5
    if word in STATIVE:
        return -1.1
    if word in DESCRIPTIONS:
        return -0.65
    if word in PRONOUNS:
        return 1.05
    if word in POSSESSIVES:
        return 0.55
    if word in ACTION_PARTICIPLES:
        return 0.75
    if word in COMPLETED_ACTIONS:
        return 0.3
    if word in {'run', 'gone', 'read', 'started', 'continued', 'worked',
                'succeeded', 'survived', 'exceeded'}:
        return 1.25
    if word.endswith('ly'):
        return -0.3
    if word.endswith(('able', 'ible')):
        return -0.45
    return 0.0


LOCATION = set('located situated positioned stationed'.split())
MOTION = set('come comes came coming go goes went gone going'.split())
STATES = set('appear appears appeared lie lies lay stand stands stood '
             'live lives lived reside resides resided remain remains remained '
             'occur occurs occurred exist exists existed sit sits sat stay '
             'stays stayed happen happens happened fall falls fell fallen '
             'originate originates originated operate operates operated '
             'start starts started'.split())
PLACEMENT = set('found born placed installed stored kept present available'.split())
IRREGULAR = set('made done held given shown seen taken kept built written known'.split())
SKIPPABLE = set('not also still already currently originally now often always '
                'only just never back'.split())
FIRST_BE = {
    ' is': 2.64, ' was': 3.10, ' are': 2.45, ' were': 2.35,
    ' be': 2.3, ' been': 1.88, ' being': 1.15, ' am': 0.89,
    'is': 1.84, 'are': 1.09, 'am': 0.12, 'be': 0.82, 'was': 2.31,
    'Be': 1.03, 'Is': 0.54, 'Are': 0.65, 'Am': 0.25,
    ' Is': 1.02, ' Am': 0.41, 'Been': 1.31, 'Being': 1.05,
}


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    word = token.strip().lower().replace('’', "'")
    if carry is None or carry[0] != doc:
        previous, raw_previous, position, be, earlier_be = '', '', 0, 0., 0.
    else:
        _, previous, raw_previous, position, be, earlier_be = carry

    value = 0.0
    if position == 0 and token in FIRST_BE:
        value = FIRST_BE[token]
    elif be:
        value = complement(word)
        if word == 'able':
            value = -0.4 if previous == 'be' else -1.4
        if word in BE and word != 'being':
            value = 1.5
        if token and not token[0].isspace() and word.isalpha():
            value = 1.1 if previous == 'be' else 0.3
            if previous == 'is' and (raw_previous.startswith('.') or
                    (previous + word).startswith(ISO_STEMS)):
                value = 1.3
            if token[:1].isupper():
                value = 0.5 if previous == 'is' else 0.0
            if previous == 'be' and word in BE:
                value = 3.0
        if token.strip() != token.strip().lower() and value < 0:
            value *= 0.35
        if previous == 'be' and value < 0:
            value *= 0.9
