    elif word in PREPOSITIONS or word == 'as':
        if previous in LOCATION:
            strength = 1.65 + 0.95 * earlier_be
        elif previous in MOTION:
            strength = 1.5 if previous.startswith('com') or previous == 'came' else 0.8
        elif previous in STATES:
            strength = 1.0
        elif previous in PLACEMENT:
            strength = 0.55 + 0.6 * earlier_be
        elif previous in SKIPPABLE:
            strength = 0.3 + 0.85 * earlier_be
        elif previous.endswith('ed') or previous in IRREGULAR:
            strength = 0.12 + 0.65 * earlier_be
        elif previous.endswith('ing'):
            strength = 0.3 + 0.4 * earlier_be
        else:
            strength = 0.5 * earlier_be
        if word in {'by', 'with', 'of'}:
            strength *= 0.5
        elif word not in {'in', 'at', 'within'}:
            strength *= 0.75
        if word == 'through':
            strength *= 0.15
        if word in {'up', 'out', 'down', 'back', 'here', 'as'}:
            strength *= 0.8
        value = -strength
    elif earlier_be:
        value = 0.3 * earlier_be * complement(word)
    if word == 'of' and previous in {'one', 'part', 'sense', 'bit', 'matter'}:
        value = -0.15 - earlier_be * (1.3 if previous == 'part' else 0.8)

