        new_be = 1.0 if be_word == token.strip().lstrip('.(/_') else 0.6
        word = be_word
    elif word in BECOME:
        new_be = 0.7
    elif word in {'get', 'gets', 'got', 'getting'}:
        new_be = 0.4
    elif word in CONTRACTIONS:
        new_be = CONTRACTIONS[word]
        if word == "'s" and previous in PRONOUNS:
            new_be = 0.5
    return (doc, word, token, position + 1, new_be, be), float(value)

programs.luna:
"""Approximate a sparse negative cue on verb-linked prepositions.

The sampled strong examples often showed negative activations in these contexts.
"""
READS = ()

PREPOSITIONS = {"in", "on", "by", "at"}
COPULAS = {"is", "are", "was", "were", "be", "been", "being"}


def step(carry, prefix, upstream):
    if len(prefix.token_strings) < 2:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0

    token, previous = prefix.token_strings[-1], prefix.token_strings[-2]
    if not token.startswith(" ") or not previous.startswith(" "):
        return None, 0.0
    word = token[1:].strip().lower()
    prior_word = previous[1:].strip().lower()
    follows_verb = (
        prior_word in COPULAS
        or prior_word.endswith("ed")
        or prior_word.endswith("ing")
    )
    if word in PREPOSITIONS and follows_verb:
        return None, -0.40
    return None, 0.0

programs.sol:
"""An orthographic r-continuation detector.

After a token ending in r (or another script's r), an i-like onset gives
large positive activation, an a-like onset negative activation. Longer
fragments and intervening spaces weaken this pattern. L-like endings have
a much weaker version. Articles and 'you' have separate boundary responses.
The constants and length decays were fitted on training text; this is a
letter-pattern approximation, not a claim about pronunciation or meaning.
"""
import math
import unicodedata

READS = ()
RHOTICS = frozenset("rрρرɾռრਰரరร")
LATERALS = frozenset("lлλل")
VOWELS = frozenset("aeiouаеёиоуыэюя")
# Each group has an inside-word amplitude and a word-boundary amplitude.
ONSETS = (
    ("iıиіιیيีิ", 2.00, 0.50),
    ("jyяь", 1.55, 0.27),
    ("aаαا", -0.71, -0.30),
    ("e", 0.55, 0.10),
    ("еэηε", 0.93, 0.21),
    ("uую", 0.39, 0.04),
    ("oоωο", 0.15, -0.055),
    ("ы", 0.82, 0.0),
)
VERBAL_SUFFIXES = frozenset({
    "ize", "ized", "izing", "izer", "izers", "ization", "izations",
    "isation", "isations",
})


def plain(text):
    return "".join(c for c in unicodedata.normalize("NFD", text.lower())
                   if not unicodedata.combining(c))


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    token = plain(raw.strip())
    previous = carry[1] if carry and carry[0] == document else ""
    state = (document, plain(raw), raw[-1:].lower())
    if not previous or not token:
        return state, 0.0
    last = previous[-1]
    if last not in RHOTICS and last not in LATERALS:
        return state, 0.0
    boundary = raw[:1].isspace()
    value = 0.0
    for letters, inside, outside in ONSETS:
        if token[0] in letters:
            value = outside if boundary else inside
            break
    if boundary:
        if token in {"a", "an"}:
            value = -0.58
        elif token == "you":
            value = 0.57
        elif token == "the":
            value = -0.16
        else:
            value /= len(token) ** 1.19
    else:
        value *= math.exp(-0.215 * max(0, len(token) - 2))
        if token in {"ing", "ings"}:
            value *= 0.45
        elif token in VERBAL_SUFFIXES:
            value *= 0.67
    value *= math.exp(-0.15 * max(0, len(previous.strip()) - 2))
    # Czech ř is a weaker rhotic trigger than ordinary r.
    if carry[2] == "ř":
        value *= 0.28
    if len(previous) > 1 and previous[-2] in VOWELS:
        value *= 1.27
    if last in LATERALS:
        value *= 0.114
    return state, float(value)

"""Mostly a negative n/N detector, not a generic n-initial-word detector.

A separate letter is strongest; capitals, repetition and early positions
amplify it. Letters within words are weaker; newline escapes are suppressed.
Smaller rules cover short n-prefixes, some n-sounds in other scripts, and
lexical associations: nation/national, nitrogen and NumPy. A small response follows a split
n onto the next piece of the same word. Unmodeled token-specific effects remain.
"""
READS = ()
COMMON_N_WORDS = frozenset('''
no not nor non now new next near never nothing neither need needs needed
'''.split())
# Common complete words/code names, rather than incomplete n-initial pieces.
WHOLE_WORD_ROOTS = (
    'name', 'num', 'node', 'null', 'none', 'nil', 'note', 'notic', 'net',
    'norm', 'negativ', 'natur', 'news', 'night', 'nov',
)


def word_response(token):
    s = token.lstrip(' \t\r\n_.,(/<')
    low = s.lower()
    if s in ('な', 'ナ', '나', 'น'):
        return -0.4
    # Strong observed associations beyond the separate letter.
    if low.startswith('national'):
        return -1.1 if s[0].isupper() else -0.5
    if low.startswith('nation'):
        return -0.4
    if low == 'nitrogen':
        return -1.48
    if low in ('np', 'numpy'):
        return -0.8 if token.startswith(' ') else -0.5
    if low in COMMON_N_WORDS or low.startswith(WHOLE_WORD_ROOTS):
        return -0.003
    if s.startswith('N') and len(s) > 1:
        return -0.32 if token.startswith(' ') or len(s) <= 3 else -0.15
    if s.startswith('n') and 1 < len(s) <= 3:
        if token.startswith(' '):
            return -0.35 if len(s) == 2 else -0.16
        return -0.05
    if s.startswith('н') and token.startswith(' '):
        return -0.12
    return -0.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    if reset:
        previous, previous_value, previous_letter_n, position = '', 0.0, False, 0
    else:
        _, previous, previous_value, previous_letter_n, position = carry
        position += 1
    # State stores just the last token/response and the document position.
    token = prefix.token_strings[-1]
    letters = ''.join(c for c in token if c.isalpha())
    separate_n = letters in ('n', 'N', 'н', 'Н', 'ن')
    attached = token == letters and previous[-1:].isalpha()
    value = word_response(token)
    if separate_n:
        if token == 'n' and previous.endswith('\\'):
            slashes = len(previous) - len(previous.rstrip('\\'))
            value = 0.065 if slashes % 2 else -0.2
        elif token.strip().startswith('\\'):
            value = -0.045
        elif letters == 'n':
            if reset and token == 'n':
                value = -2.52
            elif attached:
                value = -0.24
            elif token.startswith(' '):
                value = -0.88 - 0.63 / max(1, position) ** 0.5
            elif token.strip().startswith('('):
                value = -0.67
            else:
                punctuation = token.strip().startswith(('.', ',', '-', '/'))
                value = -1.2 if punctuation else -0.83
        elif letters == 'N':
            if reset:
                value = -5.05 if token == 'N' else -3.9
            elif attached:
                value = -0.5 if previous[-1:].isupper() else -1.05
            else:
                if token.startswith(' '):
                    value = -1.61 - 1.43 / max(1, position) ** 0.5
                else:
                    value = -1.55 if token == 'N' else -1.35
        elif letters == 'н':
            value = -1.42 if token.startswith(' ') else -0.33
        elif letters == 'Н':
            value = -3.67 if reset else -0.4 if attached else -1.5
        else:
            value = -0.84 if token.startswith(' ') else -0.26
    if (separate_n and not token.strip().startswith('\\')
            and not reset and previous[-1:].lower() in ('n', 'н', 'ن')
            and '\\' not in previous):
        value -= 0.8 if attached else 0.5
    # Echo a strong n onto the next piece, but not across a word boundary.
    if (not reset and token[:1].isalpha() and previous[-1:].isalpha()
            and previous_value < -0.5 and previous_letter_n):
        value += 0.25 * previous_value
    return (doc, token, value, separate_n, position), float(value)

"""Detect the number six in digits, number words, and calendar names.

The strongest responses are to 6, English six/sixth/sixty, and Chinese
六. Compound number words and June (the sixth month) have weaker
responses. Roman and financial numerals and Saturday are weaker still.
Only the current token is used. Small responses to unrelated vocabulary
are intentionally left at zero.
"""

READS = ()

ENGLISH_SIX_WORDS = {'six', 'sixth', 'sixty'}
CHINESE_SIX_QUANTITIES = {'六个', '六十', '六大', '六年', '六个月'}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    text = raw.strip()
    word = text.lstrip('-').casefold()
    if text == '6':
        value = 0.89
    elif text == '６':
        value = 0.86
    elif word in ENGLISH_SIX_WORDS or word == 'sixteen':
        value = 0.69 if word == 'sixteen' else 0.93
        if text.startswith('-'):
            value += 0.12
        elif raw == text:
            value -= 0.14
        if text.isupper():
            value -= 0.34
        elif text[:1].isupper():
            value -= 0.06
    elif text in {'六', '第六'}:
        value = 1.15
    elif text in CHINESE_SIX_QUANTITIES:
        value = 0.70
    elif text in {'十六', '十六条'}:
        value = 0.84
    elif text == '第六届':
        value = 0.51
    elif word == 'seis':  # Spanish and Portuguese six
        value = 0.57
    elif word == 'june':
        value = 0.54 if raw != text else 0.47
    elif text in {'VI', 'XVI', '陆', '陸'}:
        value = 0.25
    elif word == 'saturday':
        value = 0.16
    elif text == '周六':
        value = 0.35
    else:
        value = 0.0
    return None, value

programs.luna:
"""Strongly mark a token containing six; the sampled June token gets a smaller mark."""
import unicodedata

READS = ()

SIX_ACTIVATION = 0.9
JUNE_ACTIVATION = 0.55


def is_six_token(token):
    """Check common written forms: the word six, Chinese 六, or a digit valued six."""
    text = token.strip().casefold()
    if not text:
        return False
    return text == "six" or "六" in text or any(
        unicodedata.digit(char, -1) == 6 for char in text
    )


def step(carry, prefix, upstream):
    """Predict a large positive activation for six and a smaller one for June."""
    token = prefix.token_strings[-1]
    text = token.strip().casefold()
    if is_six_token(token):
        value = SIX_ACTIVATION
    elif text == "june":
        value = JUNE_ACTIVATION
    else:
        value = 0.0
    return None, value

programs.sol:
"""Approximate a predominantly written-seven response.

The digit 7 is weaker inside long numbers and decimal fractions than after
letters. Spellings of seven and related week/July words also activate it.
Smaller secondary responses cover software-operation words and separators.
Other tokens get a near-zero baseline; incidental word and whitespace
responses are intentionally not enumerated.
"""
READS = ()

# A weaker, secondary response to common code operations and separators.
CODE_WORDS = {
    "loop", "loops", "storage", "query", "queries", "stack", "label", "labels",
    "statement", "statements",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, run, decimal = "", 0, False
    else:
        _, previous, run, decimal = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    digit = len(token) == 1 and token in "0123456789"
    if digit:
        run += 1
    else:
        decimal = token == "." and run > 0
        run = 0

    value = 0.004
    if token == "7":
        if not previous:
            value = 3.17
        elif previous[-1].isalpha():
            value = 2.82
        elif decimal:
            value = 2.0
        elif run > 1:
            value = 2.3 - 0.05 * min(run, 5)
        elif previous.isspace():
            value = 2.38
        else:
            value = 2.22
    elif word in {"seven", "seventh"}:
        value = 3.2 if word == "seven" else 3.3
    elif word == "-seven":
        value = 4.4
    elif word in {"seventeen", "seventy"}:
        value = 2.37
    elif word == "七":
        value = 3.95
    elif word == "第七":  # Chinese ordinal seven
        value = 3.7
    elif word == "十七":  # Chinese seventeen
        value = 2.9
    elif word == "７":  # fullwidth digit seven
        value = 1.9
    elif word == "семь":
        value = 1.85
    elif token.strip() == "sept":  # French seven
        value = 0.77
    elif word == "vii":
        value = 1.12
    elif word in {"week", "weekly", "weeks"}:
        value = 0.8 if word != "weeks" else 0.65
    elif word in {"周", "週"}:  # Chinese week
        value = 1.0
    elif word in {"july", "jul"}:
        value = 1.35 if word == "july" else 0.6
    elif word == "sunday":
        value = 0.4
    elif word.strip("._-") in CODE_WORDS:
        value = 0.8
    elif "—" in token and len(word) <= 3:
        value = 0.4 if token.startswith(" ") else 0.6
    elif word in {"===", "!=="}:
        value = 0.75
    elif len(word) >= 3 and set(word) in ({"="}, {"-"}, {"/"}):
        value = 0.65
    elif word == ">>":
        value = 0.55
    elif len(word) >= 4 and set(word) == {"."}:
        value = 0.4
    return (doc, token, run, decimal), value

"""Negative responses to nouns ending in -ence/-ance and suffix fragments.

Common nouns calibrate the response, strongest for presence and prevalence.
Similar spellings such as experience are weak. Separate suffix tokens are
stronger than whole words. 'For instance' is weak; an immediately following
'of' retains part of the noun response. State resets at document boundaries.
"""
READS = ()

# Familiar nouns grouped by approximate response size, not by token ID.
NOUNS = {
    4.5: 'presence',
    4.0: 'prevalence',
    3.6: 'absence incidence',
    3.2: 'dependence reliance occurrence preference',
    2.6: 'reference difference instance existence relevance attendance',
    2.4: 'evidence resistance importance significance compliance',
    1.9: 'confidence entrance tolerance residence independence proximity',
    1.7: 'influence intelligence enforcement',
    1.4: 'appearance assistance substance surveillance similarity presumption',
    1.2: 'distance audience conference knowledge necessity sensitivity involvement',
    1.0: '''accordance efficiency frequency guidance hence engagement
        distinction likelihood participation opposition concentration''',
    0.8: '''performance sequence violence chance balance consequence
        advantage association agreement license defence defense offense
        symmetry''',
    0.6: 'accuracy safety satisfaction arrangement',
    0.4: 'science france sense pressure',
}
CALIBRATION = {
    word: strength for strength, words in NOUNS.items() for word in words.split()
}
WEAK = set('''experience experienced experiencing sentence enhance advance
    insurance finance dance romance freelance issuance isinstance covariance
    business businesses neuroscience agency emergency currency senza'''.split())


def strength(token):
    word = token.lower().strip().strip('_./(,\"\'[]{}:;')
    plural = word.endswith('s')
    base = word[:-1] if plural else word
    if word in WEAK or base in WEAK:
        return 0.05
    if base in CALIBRATION:
        value = CALIBRATION[base]
        if plural and base in {'difference', 'preference', 'occurrence'}:
            value *= 0.75
        return value
    # Nominal endings exposed as short word pieces.
    if word in {'ence', 'ences', 'ience', 'idence', 'istence'}:
        return 3.5
    if word in {'ference', 'erence'}:
        return 4.2
    if word in {'ferences', 'rence'}:
        return 3.0
    if word in {'ance', 'iance', 'stance', 'istance', 'inance'}:
        return 2.5
    if word == 'ances':
        return 1.75
    if word in {'enc', 'enz', 'ense', 'ness', 'eness', 'iveness'}:
        return 0.9
    if word in {'encing', 'enced', 'encer'}:
        return 2.0
    if word.endswith(('encia', 'ência', 'encias', 'ências', 'enza', 'ancia')):
        return 2.1
    if word.endswith(('ence', 'ences')):
        return 1.8
    if word.endswith(('ance', 'ances')):
        return 1.35
    if word.endswith(('enced', 'encing', 'ense', 'enses', 'ness', 'nesses')):
        return 0.6
    if word.endswith(('ency', 'encies')):
        return 0.45
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0)
    _, previous, previous_strength = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = strength(token)
    if word == 'ence':
        value = 1.9 if previous == 'h' else 3.9
    if word == 'ences' and previous == 'sequ':
        value = 1.8
    if word == 'instance' and previous == 'for':
        value = 1.1
    if word == 'of':
        value = 0.25 * previous_strength
        if previous == 'instance':
            value = 1.13
        elif previous == 'instances':
            value = 0.83
    return (doc, word, value), float(-value)

programs.haiku:
"""Component layers.0.mlp.down_proj:107: a "-ence / -ance noun" detector.

It is switched strongly negative on the last token of a word ending in "-ence" (presence,
instance, difference, reference, dependence, evidence, occurrence, ...), and weakly
negative on words ending in "-ance" (distance, assistance, resistance, importance, ...).
Everyday words that only look like they end in these suffixes (experience, science,
sentence, sequence, violence, conference, ...) are left almost silent. The word "of" right
after such a noun ("instance of", "presence of") is also pushed negative.

Everything else is 0. Each token is judged on its own text (no memory across positions
needed), so the program is a plain spelling rule plus a short list of exceptions.
"""

READS = ()

# Common words that end in -ence/-ance but do not trigger the component.
EXCEPTIONS = {
    "experience", "experiences", "science", "sciences", "sentence", "sequence",
    "sequences", "hence", "violence", "consequence", "consequences", "conference",
    "conferences", "defence", "audience", "essence", "advance", "enhance", "dance",
    "france", "finance", "insurance", "romance", "issuance",
}

STRONG = -2.7  # word ends in "-ence"
WEAK = -1.5    # word ends in "-ance"
EXCEPTION = -0.5
OF_AFTER_NOUN = -0.6  # "of" right after a "-ence" / "-ance" noun


def _word(text):
    return text.strip().lower()


def _noun_value(word):
    """The component's value on a whole word, from its spelling alone."""
    if word in EXCEPTIONS:
        return EXCEPTION
    if word.endswith(("ence", "ences", "encing", "enced", "encia")):
        return STRONG
    if word.endswith(("ance", "ances", "ancia")):
        return WEAK
    return 0.0


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    value = _noun_value(word)
    if word == "of" and len(prefix.token_strings) > 1:
        if _noun_value(_word(prefix.token_strings[-2])) < 0:
            value = OF_AFTER_NOUN
    return None, float(value)

