programs.sol:
"""A doubled-f spelling detector, strongest on short aff/off/ff fragments.

Longer words receive weaker, word-family-specific responses. Doubled-f
ligatures and Cyrillic фф respond too; 'often' and million/billion words are
secondary responses. 'Off' is reduced after stopping/payment words and boosted
in percentage discounts. These empirical rules approximate the dominant
peaks, not every small lexical response or the full sentence context.
"""
READS = ()


def response(token):
    if any(c in token for c in 'ﬀﬃﬄ'):
        return 5.9
    word = token.strip().strip("_-./'\"()[]{}:,;!?")
    lower = word.lower()
    spaced = token[:1].isspace()
    if 'фф' in lower:
        return 4.2 if lower == 'фф' else 1.5
    if 'ff' not in lower:
        if lower in {'oft', 'often'}:
            return 0.96
        if lower in {'million', 'millions', 'billion', 'billions'}:
            return 0.85
        return 0.0

    if lower in {'aff', 'off', 'eff', 'iff', 'uff', 'ff'}:
        value = {'aff': 6.2 if spaced else 6.7, 'off': 5.5, 'eff': 4.7,
                 'iff': 2.2, 'uff': 3.0, 'ff': 5.3}[lower]
        if spaced and lower == 'ff':
            value = 3.3
        if spaced and lower == 'eff':
            value = 4.0
        if word.isupper() and (lower != 'ff' or spaced):
            value += 0.6
        elif word[:1].isupper() and lower == 'off':
            value += 0.4
        return value

    if lower in {'office', 'offices'}:
        return 3.0 if not spaced or word[0].isupper() else 2.4
    if lower.startswith('offic'):
        return 1.0 if lower.endswith('s') else 1.5
    if lower.startswith('offset'):
        return 2.3
    if lower.startswith(('offer', 'offen')):
        return 1.5
    if lower.startswith('effort'):
        return 0.2 if 'less' in lower else 2.4
    if lower.startswith('effici'):
        return 1.05 if 'ency' in lower else 1.8
    if lower.startswith('effect'):
        return 1.0 if 'iv' in lower else 0.84
    if lower.startswith('affect'):
        return 2.5 if 'ion' in lower else 0.9
    if lower.startswith(('afford', 'affin', 'affili', 'affair')):
        return 1.9
    if lower.startswith('differ'):
        return 0.7 if len(lower) > 10 else 1.0
    if lower.startswith('coeff'):
        return 0.9
    if lower.startswith(('diffic', 'diffus', 'buffer')):
        return 0.35
    if lower == 'diff':
        return 1.3
    if lower.startswith('suff'):
        if lower == 'suff':
            return 2.2
        return 1.0 if lower == 'sufficient' else 0.3
    if lower.startswith('staff'):
        return 1.7
    if lower.startswith('stuff'):
        return 0.95
    if lower.startswith('coffee'):
        return 1.7

    # A doubled f near an edge is more salient in a short word fragment.
    before, after = lower.split('ff', 1)
    if after in {'e', 'en', 'er'}:
        value = 1.6 if before in {'i', 'u'} else 3.0
        return value / (1.0 + 0.4 * max(0, len(before) - 1))
    return max(0.4, 4.5 / (1.0 + 0.7 * len(before) + len(after)))


# Before 'off', these words suggest stopping, separation, or repayment.
STOPPING_VERBS = {
    'turn', 'turns', 'turned', 'turning', 'shut', 'switch', 'switched',
    'pay', 'pays', 'paid', 'paying', 'cut', 'cuts', 'cutting',
    'fall', 'falls', 'fell', 'falling', 'trade', 'back',
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = response(token)
    if token.lower().strip() in {'off', '-off'}:
        if previous in {'%', 'percent'}:
            value = 7.6
        elif previous in STOPPING_VERBS:
            value = 4.2
        elif token.strip() == '-off':
            value = 5.0
    return (doc, token.strip().lower()), float(value)

programs.haiku:
"""Layer-0 MLP output channel 108 (layers.0.mlp.down_proj:108).

A spelling detector for the letter pair "ff" in English words, read off the current
token alone. Its strongest response is to bare "off", "aff", "eff" and "ff" fragments
(" off", "OFF", "-off", "aff"). Words built on those fragments respond less, with
"office" and "effort" (and their relatives) strongest among them. Other "ff" words
respond weakly, and a few words that share the same meaning in other languages
(官 / 办公室 "office", 努力 "effort") respond moderately. Most tokens are near zero.
The program ignores context: the component is driven by which token it is.
"""

READS = ()

BARE = {"off", "aff", "eff", "ff"}
PREFIXES = ("off", "aff", "eff")
OFFICE_EFFORT = ("offic", "effort")
MODERATE = {"often", "oft", "million", "millions", "billion", "comfortable", "comfort"}
OTHER_LANGUAGE = {"官", "官方", "办公室", "办公", "努力", "офис", "офи", "эфф", "эффектив", "фф"}
LOW_FF = {"difficult", "difficulty", "buffer", "buffers", "suffer", "suffered", "suffering"}


def word_of(token):
    # Lower-case the token and drop the leading space, dash, quote or underscore it may carry.
    return token.strip().lower().strip("-_'/")


def activation(token):
    w = word_of(token)
    if w in BARE:
        return 5.5
    if w in OTHER_LANGUAGE:
        return 1.5
    if "ff" not in w:
        return 0.9 if w in MODERATE else 0.0
    if w in LOW_FF:
        return 0.3
    if len(w) <= 4:
        return 2.0  # short fragments: iff, uff, diff, jeff, ffi, ffen
    if w.startswith(OFFICE_EFFORT):
        return 2.5  # office, officer, offices, effort, efforts
    if w.startswith(PREFIXES):
        return 1.4  # offer, offset, affect, effective, affordable
    return 0.9  # other ff words: staff, coffee, different, difference, effect


def step(carry, prefix, upstream):
    return carry, float(activation(prefix.token_strings[-1]))

