programs.sol:
"""A local ed/eed-spelling detector, strongest for feed and seed.

Short rhyming word families get negative values. Most inflections and
compounds are weaker. A split-off ed is distinguished from a long
word's ordinary past-tense suffix. Carry stores only the current word tail
and resets at document boundaries. Most other tokens get zero.
"""
import re

READS = ()

# Word families sharing the ed/eed spelling, not arbitrary token IDs.
RHYMES = {
    'feed': -4.6,
    'seed': -3.25,
    'breed': -1.95,
    'weed': -2.15,
    'reed': -1.7,
    'deed': -1.35,
    'bleed': -1.75,
    'heed': -.8,
    'greed': -1.2,
}
INFLECTION = {
    '': 1.0,
    's': .75,
    'ing': .77,
    'er': .72,
    'ers': .72,
    'ed': .6,
    'y': .45,
}
# When these verb stems precede "bed", it is past tense, not a bed compound.
PAST_VERBS = {
    'absorb', 'adsorb', 'comb', 'bomb', 'barb', 'probe',
    'rob', 'rub', 'scrub', 'sob', 'throb',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    piece = raw.strip().lstrip('._/(-=')
    word = piece.lower()
    joined = raw[:1].isalpha() and bool(previous)
    value = 0.0

    for stem, strength in RHYMES.items():
        if word.startswith(stem) and word[len(stem):] in INFLECTION:
            value = strength * INFLECTION[word[len(stem):]]
            if stem == 'feed' and piece[:1].isupper():
                value *= 1.1
            if stem == 'feed' and raw.startswith('-'):
                value *= .75
            break

    if word in {'bed', 'beds'}:
        value = -1.1
        if raw == 'bed':
            value = -1.95
            if previous + 'b' in PAST_VERBS or previous + 'be' in PAST_VERBS:
                value = 0.0
    elif word == 'fed':
        value = -1.95 if piece.islower() else -1.3
        if raw.startswith('-'):
            value = -1.4
    elif word == 'eed':
        value = -2.75
    elif word == 'ed':
        if not joined:
            value = -.9
        elif previous.endswith('e'):
            value = -2.6
        elif previous.endswith('b'):
            value = .05
        elif len(previous) <= 2:
            value = -1.25
        elif len(previous) == 3:
            value = -.55
        else:
            value = -.4 if piece.isupper() else -.2
    elif word.startswith('ed') and len(word) <= 5:
        if word == 'eds':
            value = -2.8 if joined and previous.endswith('e') else -1.1
        elif word == 'eding':
            value = -3.5 if joined and previous.endswith('e') else -1.2
        elif word == 'eder':
            value = -2.3 if joined and previous.endswith(('f', 'e')) else -1.2
        elif word == 'eded':
            value = -1.6
        elif re.fullmatch('ed[aeiouyrsn]+', word):
            value = -.7
    elif word.startswith(('embed', 'feedback')):
        value = -.72
    elif word == 'sed' and not piece.isupper():
        value = -.55 if raw[:1].isspace() else -.15
    elif word == 'bred':
        value = -.6

    combined = previous + raw if raw[:1].isalpha() else raw
    match = re.search(r'[A-Za-z]+$', combined)
    tail = match[0][-30:].lower() if match else ''
    return (doc, tail), float(value)

programs.luna:
"""Recognize a few early-layer text cues: the Cyrillic letter с, commas and
dashes in nearby Cyrillic text, and word pieces ending in с. Other tokens
usually have activations near zero, so they receive zero.
"""

READS: tuple[str, ...] = ()

DASHES = frozenset("-‐‑‒–—―−")


def _cyrillic(text):
    return any("\u0400" <= ch <= "\u052f" for ch in text)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    bare = token.strip()

    if bare == "с":
        return None, -3.1
    if bare == "С":
        return None, -2.5

    start = max(0, prefix.position - 8)
    document = prefix.document_ids[-1]
    while start < prefix.position and prefix.document_ids[start] != document:
        start += 1
    recent = "".join(prefix.token_strings[start:-1])
    cyrillic_context = _cyrillic(recent)

    if bare == ",":
        return None, -0.95 if cyrillic_context else 0.0

    if bare in DASHES:
        return None, 0.85 if cyrillic_context else 0.0

    if bare.endswith("с") and len(bare) > 1:
        return None, -0.85

    return None, 0.0

programs.sol:
"""Text-boundary cues, using only this token and the previous token.

Split escape suffixes are positive, especially n completing a backslash-n
sequence. Extra backslashes weaken this response; nearby punctuation makes
small adjustments. Joined hexadecimal/Unicode escape prefixes, tabs and
carriage returns have modest negative responses instead.

Capitalized openings are negative after unpunctuated text, strongest for
The and demonstratives. Function words and punctuation in the preceding
token weaken this cue. Other title-case words get a much weaker response.
These coarse rules omit word-specific variation and most small activations.
State resets at each document boundary.
"""
READS = ()

REFERENTIAL_OPENERS = {'This', 'These', 'Those', 'There'}
SUBJECT_PRONOUNS = {'It', 'We', 'They', 'He', 'She', 'You'}
COMMON_OPENERS = set(
    'In On At To From For With By As If But And Or So That All '
    'When Where What Why How Thank Please'.split()
)
FUNCTION_WORDS = set(
    'a an the of to in on at by for from with without and or but as than '
    'into over under is are was were be been being can could will would '
    'shall should may might must have has had do does did my your his her '
    'its our their this that these those which whose when where who how '
    'if not no'.split()
)
ESCAPE_SUFFIXES = {'n', 't', 'r', 'x', 'u', 'b', 'f', 'v'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    state = (doc, token)

    if token in ESCAPE_SUFFIXES and prev.endswith('\\'):
        slashes = len(prev) - len(prev.rstrip('\\'))
        if token == 'n':
            strength = 0.76
            punctuation = prev.rstrip('\\')
            if punctuation.endswith(('()', '.')):
                strength -= 0.07
            elif punctuation.endswith('\\"'):
                strength -= 0.04
            elif punctuation.endswith((',', ';', "'", '"', '`')):
                strength += 0.06
        elif token in {'t', 'r'}:
            strength = 0.38
        else:
            strength = 0.18
        return state, strength / (1.0 + 0.4 * (slashes - 1))
    if token.startswith(('\\x', '\\u')):
        return state, -0.18
    if token == '\\t':
        return state, -0.05
    if token == '\\r':
        return state, -0.19

    word = token.strip()
    if not word.isalpha() or not word.istitle() or word == 'I':
        return state, 0.0
    if word == 'The':
        strength = 0.70
    elif word in REFERENTIAL_OPENERS:
        strength = 0.66
    elif word in SUBJECT_PRONOUNS:
        strength = 0.47
    elif word in {'A', 'An'}:
        strength = 0.20
    elif word in COMMON_OPENERS:
        strength = 0.36
    elif len(word) >= 6 and word.endswith('ing'):
        strength = 0.20
    elif len(word) >= 3:
        strength = 0.07
    else:
        return state, 0.0

    if not token.startswith(' '):
        strength *= 0.6 if strength > 0.1 else 0.0
    if not prev:
        return state, 0.0
    if not token.startswith(' ') and '\n' in prev:
        return state, 0.02 if strength > 0.1 else 0.0

    previous_word = prev.strip()
    if prev[-1].isalnum():
        if previous_word.lower() in FUNCTION_WORDS:
            factor = 0.32 if previous_word.islower() else 0.08
        elif previous_word.istitle():
            factor = 0.6
        elif previous_word.isupper():
            factor = 1.0
        elif prev[-1].isdigit():
            factor = 0.65 if word == 'The' else 1.0
        else:
            factor = 1.0
    elif prev.endswith((',', ';')):
        factor = 0.20
    elif prev[-1] in ")]\"'":
        factor = 0.35
    elif '\n' in prev or prev.isspace():
        factor = 0.15
    elif prev.endswith(('.', ':')):
        factor = 0.0
    else:
        factor = 0.10
    baseline = 0.02 if token.startswith(' ') else 0.0
    return state, baseline - strength * factor

