            if t == 'الى':
                v = .13  # The preposition 'to', not a definite article.
            elif base == 'الله':
                v = 3.0
            elif not n:
                v, strength = bare, 1.0
            return None, v * strength * (1.0 if s.startswith(' ') else .4)
        return None, (.35 if not s.startswith(' ') else
                      -.25 if len(t) == 1 else .15 if len(t) >= 3 else 0.)
    m = re.fullmatch(r'(\.?)(get|Get|set)([A-Z]\w*)?', t)
    if m:
        dot, verb, name = m.groups()
        if not name:
            return None, {'get': 1.22 if dot else .23,
                          'Get': .64 if dot else .18,
                          'set': .39 if dot else 0.0}[verb]
        if verb == 'Get':
            return None, 1.1
        if verb == 'set':
            return None, 1.7 if dot else 1.2
        return None, 2.73 if dot else 2.4
    return None, 0.0

programs.luna:
"""Predict responses to chat-control markers, Arabic alif-lam word starts, and code accessors."""

READS = ()

CHAT_MARKERS = {
    "<|im_start|>": 2.45,
    "<|im_end|>": 0.80,
    "<tool_response>": 2.23,
    "</tool_response>": 1.02,
    "<tool_call>": 0.31,
    "</tool_call>": 0.49,
    "<think>": 0.54,
    "</think>": 5.20,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]

    # These markers introduce or close a chat message, tool exchange, or thought.
    if token in CHAT_MARKERS:
        return None, CHAT_MARKERS[token]

    # Arabic word pieces beginning with "ال" often carry the definite article.
    if token.lstrip().startswith("ال"):
        return None, 7.7

    # In code, member getters are a modest positive cue; other dotted names are weaker.
    if token.startswith(".get"):
        return None, 2.2
    if token.startswith(".set"):
        return None, 0.77
    if token.startswith(".") and len(token) > 1 and token[1].isalpha():
        return None, 0.12
    if token == "unwrap":
        return None, 1.1
    return None, 0.0

"""Use visible word shape as a weak proxy for name-like and technical terms.

The rules give small positive estimates to mixed-case and identifier-like
pieces, unusual capitalization, non-Latin text, and long spellings. They do not
identify a particular entity or infer a topic from context.
"""
READS = ()

import unicodedata

SENTENCE_WORDS = {
    "A", "An", "And", "As", "At", "But", "By", "For", "From", "He",
    "Her", "Here", "How", "I", "If", "In", "It", "Its", "My", "No",
    "Of", "On", "Or", "Our", "She", "So", "That", "The", "Their",
    "There", "They", "This", "To", "We", "What", "When", "Where",
    "Which", "Who", "Why", "You",
}
CODE_WORDS = {
    "class", "const", "def", "enum", "float", "function", "import",
    "int", "let", "long", "new", "private", "public", "return",
    "static", "string", "struct", "void", "var",
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip()
    letters = [c for c in word if c.isalpha()]
    if not letters:
        return None, 0.0

    if any(c.islower() for c in word) and any(c.isupper() for c in word):
        return None, 0.09
    if any(c in word for c in "_.$") and len(word) > 2:
        return None, 0.08

    if letters[0].isupper():
        if word in SENTENCE_WORDS:
            return None, 0.0
        if all(c.isupper() for c in letters) and len(letters) >= 2:
            return None, 0.08
        if len(letters) >= 4:
            return None, 0.08
        return None, 0.0

    if any(ord(c) > 127 and unicodedata.category(c).startswith("L")
           for c in letters):
        return None, 0.07

    if word.lower() in CODE_WORDS:
        return None, 0.09

    # Long, unusual spellings are a weak proxy for technical or rare terms.
    if len(letters) >= 8 and any(c in word.lower() for c in "qzx"):
        return None, 0.02
    if len(letters) >= 10:
        return None, 0.012

    return None, 0.0

programs.sol:
"""A lexical primacy response, not a general detector of ordering.

Primary and secondary labels have large negative values; first, beginnings,
and words stressing predominance or exclusivity have smaller ones. The
same words in code and several common translations also respond. A prim-
or Russian first/main stem can continue responding on its next suffix.
Unrecognized tokens receive zero. Carry remembers only the last word and
its document, so fragments never join across document boundaries.
"""

READS = ()

LABELS = {
    'primary': -6.7, 'primarily': -4.1, 'primaries': -4.9,
    'secondary': -3.0, 'tertiary': -1.25, 'primarykey': -2.1,
    'prima': -1.2, 'primal': -1.1, 'chiefly': -1.85,
    'principally': -1.35, 'principalmente': -1.55,
}
# Related word classes; weights are approximate training means.
STRONG_QUALIFIERS = {
    'mainly', 'initially', 'ultimately', 'foremost', 'solely', 'firstly',
}
MODERATE_QUALIFIERS = {
    'prime', 'primes', 'mostly', 'predominantly', 'originally',
    'ultimate', 'namely', 'dual', 'auxiliary',
}
MILD_QUALIFIERS = {
    'sole', 'chief', 'particularly', 'specifically', 'fundamentally',
    'largely', 'secondly', 'primitive',
}
FIRST_EQUIVALENTS = {
    'primer', 'primera', 'primeiro', 'primeira', 'primo', 'première',
    'erste', 'ersten', 'erster', 'første', 'pierws',
    '第一', '的第一', '第一次', '第一个', '首次', '首先',
}
BEGINNINGS = {'初步', '初心', '初次', '当初', '初中'}
MAIN_OR_INITIAL = {
    '主要', '的主要', '为主', '最初', '初期', '初めて', '辅助',
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    word = token.strip().lstrip('_-.(').lower()
    value = LABELS.get(word, 0.0)
    if word == 'first':
        value = -1.1 if token.startswith((' First', ' FIRST')) else -0.9
    elif word == 'prim':
        value = -2.5 if token.strip().startswith('P') else -1.75
    elif word in STRONG_QUALIFIERS:
        value = -0.95
    elif word in MODERATE_QUALIFIERS:
        value = -0.65
    elif word in MILD_QUALIFIERS:
        value = -0.43
    elif word in FIRST_EQUIVALENTS:
        value = -0.8
    elif word in BEGINNINGS:
        value = -1.55
    elif word in MAIN_OR_INITIAL:
        value = -0.6
    elif word in {'primero', 'перв', 'основном', '主要是'}:
        value = -1.3
    elif word.startswith('перв'):
        value = -0.8
    elif word == 'основ':
        value = -0.4
    elif word == '初':
        value = -2.2
    elif word == '初级':
        value = -3.0
    elif word == 'firstname':
        value = -0.6
    if token and token[0].islower() and token.isalpha():
        if prev == 'prim':
            value -= 3.6 if word == 'arily' else 0.65
        elif prev == 'перв':
            value -= 0.75
        elif prev == 'основ' and word.startswith('н'):
            value -= 0.45
    return (doc, word), float(value)

programs.luna:
"""Predict a negative response for words about firstness, primacy, or being
main or sole. Russian ordinal stems also pass a response to their next suffix.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    lower = token.lower()
    word = "".join(ch for ch in lower if ch.isalpha())
    doc = prefix.document_ids[-1]

    previous_doc, continuation_value = carry or (None, 0.0)
    if previous_doc != doc:
        continuation_value = 0.0

    # The first subword of an inflected Russian word is often the signal;
    # carry it onto its unspaced suffix pieces, but not into a new document.
    if word and not token[:1].isspace() and continuation_value:
        if all("\u0400" <= ch <= "\u052f" for ch in word):
            return (doc, 0.0), continuation_value

    value = 0.0
    next_piece = 0.0

    if word.startswith(("first", "перв", "erst", "premier", "pierw")):
        value, next_piece = -0.9, -0.65
    elif word.startswith("втор"):
        value, next_piece = -0.27, -0.65
    elif word.startswith(("primar", "primer", "primeir")):
        value = -0.9
    elif word.startswith(("prim", "foremost", "principal")):
        value = -0.55
    elif word.startswith(("main", "sole")):
        value = -0.65
    elif word.startswith(("mostly", "chief")):
        value = -0.48
    elif word in {"首次", "最初", "主要", "第一", "一次"}:
        value = -0.65

    return (doc, next_piece), float(value)
